window.QDATA[1] = [
  {t:"Fondamentaux cloud",q:"Qu'est-ce que le cloud computing selon Google Cloud ?",o:["Un réseau de serveurs physiques dans un seul datacenter","La livraison de ressources informatiques à la demande via Internet","Un logiciel installé localement sur chaque machine","Un protocole de communication entre ordinateurs"],a:1,e:"Le cloud computing désigne la livraison à la demande de ressources informatiques (calcul, stockage, réseau) via Internet, avec facturation à l'usage."},
  {t:"Fondamentaux cloud",q:"Quel modèle de service cloud laisse le plus de responsabilités à l'utilisateur ?",o:["SaaS","PaaS","IaaS","FaaS"],a:2,e:"L'IaaS (Infrastructure as a Service) fournit uniquement l'infrastructure (VM, réseau, stockage). L'utilisateur gère OS, middleware, applications et données."},
  {t:"Fondamentaux cloud",q:"Dans le modèle PaaS, que gère le fournisseur cloud ?",o:["Uniquement le matériel physique","L'infrastructure, l'OS et le middleware","L'application et les données uniquement","Rien, tout est géré par l'utilisateur"],a:1,e:"En PaaS, le fournisseur gère l'infrastructure sous-jacente, l'OS et le middleware. L'utilisateur se concentre sur le développement et le déploiement des applications."},
  {t:"Fondamentaux cloud",q:"Qu'est-ce qu'un déploiement cloud hybride ?",o:["Utiliser uniquement des services Google Cloud","Combiner infrastructure on-premise et services cloud publics","Utiliser deux fournisseurs cloud différents","Déployer des applications sur mobile et desktop"],a:1,e:"Un cloud hybride combine une infrastructure on-premise (ou cloud privé) avec un cloud public, permettant de faire communiquer les deux environnements."},
  {t:"Fondamentaux cloud",q:"Quel avantage principal offre le cloud par rapport à l'infrastructure traditionnelle ?",o:["Sécurité absolument garantie","Élasticité et mise à l'échelle à la demande","Coûts toujours inférieurs sans exception","Performances toujours supérieures"],a:1,e:"L'élasticité permet d'augmenter ou réduire les ressources selon les besoins en temps réel, sans investissement matériel initial (CapEx converti en OpEx)."},
  {t:"Fondamentaux cloud",q:"Que signifie 'CapEx' dans le contexte IT ?",o:["Capital Expenditure — dépenses en capital pour actifs physiques","Cloud Application Exchange — marketplace de services","Capacity Extension — extension de capacité serveur","Certified Application Expert — certification professionnelle"],a:0,e:"CapEx (Capital Expenditure) désigne les dépenses d'investissement pour acquérir des actifs physiques (serveurs, datacenters). Le cloud permet de passer au modèle OpEx (dépenses opérationnelles)."},
  {t:"Fondamentaux cloud",q:"Quel est l'avantage du modèle OpEx pour une entreprise utilisant le cloud ?",o:["Propriété permanente des ressources","Paiement à l'usage, sans investissement initial","Contrôle total du matériel physique","Indépendance totale vis-à-vis du fournisseur"],a:1,e:"Le modèle OpEx (Operating Expenditure) du cloud permet de payer uniquement les ressources consommées, améliorant la trésorerie et réduisant les risques d'investissement."},
  {t:"Fondamentaux cloud",q:"Qu'est-ce que la 'haute disponibilité' dans le cloud ?",o:["Un serveur qui ne tombe jamais en panne","La capacité d'un système à rester opérationnel malgré des défaillances","Des performances maximales garanties 24h/24","Un accès administrateur permanent aux ressources"],a:1,e:"La haute disponibilité désigne la capacité d'un système à maintenir son fonctionnement et son accessibilité en minimisant les temps d'arrêt, souvent exprimée en pourcentage (ex: 99,9%)."},
  {t:"Fondamentaux cloud",q:"Que représente un SLA (Service Level Agreement) dans le cloud ?",o:["Un contrat définissant les niveaux de service garantis","Un langage de programmation pour scripts cloud","Un protocole de sécurité réseau","Un outil de monitoring des performances"],a:0,e:"Un SLA est un accord contractuel entre le fournisseur cloud et le client définissant les niveaux de service garantis (disponibilité, temps de réponse) et les compensations en cas de non-respect."},
  {t:"Fondamentaux cloud",q:"Quelle est la différence entre 'scalabilité verticale' et 'scalabilité horizontale' ?",o:["Verticale = ajouter des machines, Horizontale = augmenter les ressources d'une machine","Verticale = augmenter les ressources d'une machine, Horizontale = ajouter des machines","Verticale = cloud public, Horizontale = cloud privé","Elles sont identiques, juste des termes différents"],a:1,e:"La scalabilité verticale (scale up) augmente les ressources d'une instance existante. La scalabilité horizontale (scale out) ajoute de nouvelles instances pour distribuer la charge."},
  {t:"GCP Organisation",q:"Qu'est-ce que Google Cloud Platform (GCP) ?",o:["Un système d'exploitation cloud de Google","Une suite de services cloud fournis par Google","Un navigateur web optimisé pour le cloud","Un protocole réseau développé par Google"],a:1,e:"Google Cloud Platform est l'ensemble des services cloud publics de Google, incluant calcul, stockage, bases de données, IA/ML, réseau et outils DevOps."},
  {t:"GCP Organisation",q:"Comment les ressources GCP sont-elles organisées hiérarchiquement ?",o:["Projets → Dossiers → Organisation","Organisation → Dossiers → Projets → Ressources","Ressources → Projets → Comptes → Régions","Régions → Zones → Projets → Ressources"],a:1,e:"La hiérarchie GCP est : Organisation (racine) → Dossiers (optionnels) → Projets → Ressources. Cette structure permet une gestion centralisée des politiques et des accès."},
  {t:"GCP Organisation",q:"Quel est le rôle d'un 'Projet' dans GCP ?",o:["Un datacenter physique Google","L'unité de base pour organiser et facturer les ressources GCP","Un type de machine virtuelle","Un service de stockage d'objets"],a:1,e:"Le Projet est l'unité fondamentale d'organisation dans GCP. Il regroupe des ressources, gère la facturation, contrôle les APIs activées et définit les permissions d'accès."},
  {t:"GCP Organisation",q:"Qu'est-ce que Google Cloud Console ?",o:["Un terminal en ligne de commande","Une interface web graphique pour gérer les ressources GCP","Un service de base de données","Un outil de déploiement automatique"],a:1,e:"Google Cloud Console est l'interface web graphique permettant de gérer, surveiller et configurer tous les services et ressources GCP via un navigateur."},
  {t:"GCP Organisation",q:"Quel outil en ligne de commande est utilisé pour interagir avec GCP ?",o:["aws-cli","azure-cli","gcloud","gcpctl"],a:2,e:"La CLI gcloud (Google Cloud SDK) est l'outil principal en ligne de commande pour interagir avec les services GCP, gérer les ressources et automatiser les tâches."},
  {t:"GCP Organisation",q:"Que sont les 'régions' dans GCP ?",o:["Des zones de tarification différentes","Des emplacements géographiques hébergeant des datacenters Google","Des groupes d'utilisateurs par pays","Des catégories de services cloud"],a:1,e:"Les régions GCP sont des emplacements géographiques spécifiques (ex: europe-west1, us-central1) où Google exploite des datacenters. Chaque région contient plusieurs zones."},
  {t:"GCP Organisation",q:"Qu'est-ce qu'une 'zone' dans GCP ?",o:["Un pays entier couvert par GCP","Une zone de déploiement isolée au sein d'une région","Un réseau privé virtuel","Une catégorie tarifaire"],a:1,e:"Une zone est un déploiement isolé au sein d'une région (ex: europe-west1-b). Les zones offrent isolation des pannes et permettent la haute disponibilité en répartissant les ressources."},
  {t:"GCP Organisation",q:"Pourquoi déployer des ressources dans plusieurs zones ?",o:["Pour réduire les coûts","Pour améliorer la haute disponibilité et la résilience aux pannes","Pour augmenter les performances réseau","Pour accéder à plus de services"],a:1,e:"Déployer dans plusieurs zones protège contre les pannes d'une zone spécifique. Si une zone est défaillante, les ressources dans d'autres zones continuent de fonctionner."},
  {t:"GCP Organisation",q:"Qu'est-ce que Cloud Shell dans GCP ?",o:["Un service de stockage d'objets","Un environnement de terminal virtuel accessible depuis le navigateur","Un outil de visualisation de données","Un service de messagerie cloud"],a:1,e:"Cloud Shell est un environnement de terminal Linux virtuel hébergé dans le cloud, accessible directement depuis la Console GCP, avec gcloud SDK et outils pré-installés."},
  {t:"GCP Organisation",q:"Comment GCP facture-t-il généralement ses services ?",o:["Abonnement mensuel fixe uniquement","À l'usage selon les ressources consommées","Par nombre d'utilisateurs uniquement","Par licence annuelle fixe"],a:1,e:"GCP utilise principalement un modèle de facturation à l'usage (pay-as-you-go) : les clients paient selon les ressources effectivement consommées (compute, stockage, transfert de données)."},
  {t:"Concepts cloud avancés",q:"Qu'est-ce que la 'tolérance aux pannes' (fault tolerance) ?",o:["La capacité à prévenir toutes les pannes","La capacité d'un système à continuer fonctionner malgré des défaillances de composants","L'absence totale de bugs dans le code","La durée de vie garantie du matériel"],a:1,e:"La tolérance aux pannes est la capacité d'un système à maintenir son fonctionnement même lorsque certains composants échouent, grâce à la redondance et aux mécanismes de basculement."},
  {t:"Concepts cloud avancés",q:"Que signifie 'infrastructure immuable' dans le contexte cloud ?",o:["Une infrastructure qui ne peut jamais être modifiée","Une approche où les serveurs ne sont jamais modifiés en place, mais remplacés","Une infrastructure permanente sans possibilité de suppression","Des ressources cloud sans limite de temps"],a:1,e:"L'infrastructure immuable consiste à remplacer les instances au lieu de les modifier en place. Pour chaque changement, une nouvelle image est déployée, garantissant la cohérence et la reproductibilité."},
  {t:"Concepts cloud avancés",q:"Qu'est-ce que le 'DevOps' dans le contexte GCP ?",o:["Un service Google spécifique","Une culture combinant développement et opérations pour accélérer les livraisons","Un langage de programmation pour le cloud","Un protocole de sécurité réseau"],a:1,e:"DevOps est une culture et un ensemble de pratiques qui combinent développement logiciel et opérations IT pour raccourcir les cycles de développement et livrer en continu des logiciels de qualité."},
  {t:"Concepts cloud avancés",q:"Qu'est-ce qu'un conteneur dans le contexte cloud ?",o:["Un service de stockage d'objets","Une unité légère et portable d'application avec ses dépendances","Un type de machine virtuelle","Un réseau privé virtuel"],a:1,e:"Un conteneur encapsule une application avec toutes ses dépendances dans un package isolé, léger et portable. Contrairement aux VMs, les conteneurs partagent l'OS hôte."},
  {t:"Concepts cloud avancés",q:"Quelle est la différence entre une VM et un conteneur ?",o:["Les VMs sont plus récentes que les conteneurs","Les VMs incluent leur propre OS, les conteneurs partagent l'OS hôte","Les conteneurs sont plus lents que les VMs","Il n'y a aucune différence fonctionnelle"],a:1,e:"Les VMs virtualisent le matériel et incluent un OS complet. Les conteneurs virtualisent au niveau OS et partagent le noyau hôte, les rendant plus légers, rapides à démarrer et efficaces."},
  {t:"Concepts cloud avancés",q:"Que signifie 'serverless' dans le cloud ?",o:["Absence totale de serveurs physiques dans le monde","Modèle où le développeur ne gère pas les serveurs, seulement le code","Des serveurs qui ne consomment aucune énergie","Un service uniquement disponible sans connexion Internet"],a:1,e:"Le serverless est un modèle d'exécution où le fournisseur cloud gère entièrement l'infrastructure. Le développeur écrit uniquement le code fonctionnel ; la mise à l'échelle est automatique."},
  {t:"Concepts cloud avancés",q:"Qu'est-ce que l'orchestration de conteneurs ?",o:["La création manuelle de conteneurs","La gestion automatisée du déploiement, mise à l'échelle et opération des conteneurs","Un outil de monitoring réseau","Un service de stockage pour conteneurs"],a:1,e:"L'orchestration de conteneurs automatise le déploiement, la mise à l'échelle, le réseau et la gestion du cycle de vie des conteneurs. Kubernetes est l'outil d'orchestration standard."},
  {t:"Concepts cloud avancés",q:"Qu'est-ce que l'architecture microservices ?",o:["Une application construite comme un seul bloc monolithique","Une architecture décomposant une application en petits services indépendants","Un service cloud de petite taille","Un protocole réseau miniaturisé"],a:1,e:"Les microservices décomposent une application en petits services indépendants, chacun responsable d'une fonction spécifique, communiquant via APIs. Cela facilite le déploiement et la scalabilité."},
  {t:"Concepts cloud avancés",q:"Qu'est-ce que le 'load balancing' (équilibrage de charge) ?",o:["Une technique pour réduire la taille des fichiers","La distribution automatique du trafic entre plusieurs serveurs","Un service de compression de données","Un protocole de chiffrement réseau"],a:1,e:"L'équilibrage de charge distribue le trafic entrant entre plusieurs serveurs backend, évitant la surcharge d'un seul serveur et améliorant la disponibilité et les performances."},
  {t:"Concepts cloud avancés",q:"Que signifie CDN (Content Delivery Network) ?",o:["Un réseau de distribution de contenu utilisant des serveurs répartis géographiquement","Un protocole de sécurité pour le transfert de données","Un service de gestion des bases de données","Un système de messagerie cloud"],a:0,e:"Un CDN est un réseau de serveurs distribués géographiquement qui met en cache et distribue le contenu (images, vidéos, pages web) depuis des emplacements proches des utilisateurs finaux."},
  {t:"Concepts cloud avancés",q:"Qu'est-ce que l'API (Application Programming Interface) dans le cloud ?",o:["Un protocole réseau sécurisé","Une interface permettant à des applications de communiquer entre elles","Un type de base de données","Un outil de surveillance des performances"],a:1,e:"Une API définit les règles permettant à des applications de communiquer entre elles. Dans le cloud, les APIs RESTful permettent d'accéder aux services et ressources cloud de manière programmatique."},
  {t:"Avantages GCP",q:"Qu'est-ce que le réseau mondial de fibres optiques de Google apporte à GCP ?",o:["Des services uniquement disponibles en Amérique du Nord","Des latences ultra-faibles et un transfert de données privé entre régions","Un accès gratuit à tous les services","Une connexion uniquement disponible pour les entreprises"],a:1,e:"Le réseau de fibres optiques privé de Google connecte ses datacenters mondiaux, offrant des latences très faibles, un débit élevé et un routage interne sécurisé sans passer par l'Internet public."},
  {t:"Avantages GCP",q:"Qu'est-ce que le programme de durabilité de Google Cloud ?",o:["Un programme pour réduire les factures des clients","L'engagement de Google à fonctionner avec 100% d'énergie renouvelable","Un service d'optimisation de code","Un protocole de sauvegarde des données"],a:1,e:"Google s'engage depuis 2017 à être le premier grand fournisseur cloud à fonctionner 24/7 avec de l'énergie sans carbone. Google Cloud compense ses émissions pour être neutre en carbone."},
  {t:"Avantages GCP",q:"Quel outil GCP permet d'estimer les coûts avant déploiement ?",o:["Cloud Monitor","Cloud Pricing Calculator","Cost Advisor","Budget Estimator"],a:1,e:"Le Google Cloud Pricing Calculator permet d'estimer les coûts mensuels avant de déployer des ressources, en configurant les services, régions, volumes et durées d'utilisation."},
  {t:"Avantages GCP",q:"Que sont les 'sustained use discounts' de GCP ?",o:["Des réductions pour les startups uniquement","Des réductions automatiques appliquées lorsque les VMs sont utilisées plus d'un certain temps par mois","Des promotions saisonnières","Des réductions pour l'achat de licences logicielles"],a:1,e:"Les sustained use discounts sont des réductions automatiques (jusqu'à 30%) appliquées aux instances Compute Engine lorsqu'elles fonctionnent plus de 25% du mois, sans engagement préalable."},
  {t:"Avantages GCP",q:"Qu'est-ce qu'une 'committed use discount' sur GCP ?",o:["Une réduction automatique sans engagement","Une réduction en échange d'un engagement d'utilisation sur 1 ou 3 ans","Une réduction pour les étudiants","Une réduction pour les organisations à but non lucratif"],a:1,e:"Les committed use discounts offrent des réductions importantes (jusqu'à 57%) en échange d'un engagement d'utilisation d'une quantité fixe de ressources Compute Engine sur 1 ou 3 ans."},
  {t:"Avantages GCP",q:"Quelle est la politique de Google concernant les données clients sur GCP ?",o:["Google utilise les données clients pour améliorer ses propres produits","Google ne vend pas les données clients et ne les utilise pas pour ses publicités","Google partage les données avec ses partenaires commerciaux","Google n'a aucune politique de confidentialité spécifique"],a:1,e:"Google Cloud s'engage à ne pas vendre les données clients et à ne pas les utiliser pour cibler des publicités. Les données des clients GCP sont distinctes des données utilisées pour les produits grand public."},
  {t:"Avantages GCP",q:"Qu'est-ce que Google Cloud Marketplace ?",o:["Une boutique en ligne pour acheter du matériel informatique","Un catalogue de solutions logicielles tiers prêtes à déployer sur GCP","Un service de vente de domaines web","Un réseau social pour développeurs GCP"],a:1,e:"Cloud Marketplace est un catalogue de solutions logicielles, VM images et services tiers préconfigurés, facilement déployables sur GCP avec facturation intégrée."},
  {t:"Avantages GCP",q:"Que proposent les 'Free Tier' et crédits de démarrage de GCP ?",o:["Un accès gratuit et illimité à tous les services GCP","Des crédits initiaux et des niveaux d'utilisation gratuits pour tester les services","Un accès gratuit uniquement pour les étudiants","Des services gratuits uniquement en heures creuses"],a:1,e:"GCP offre des crédits de démarrage (300$ pour les nouveaux clients), un niveau gratuit permanent avec des quotas mensuels gratuits pour certains services (Cloud Functions, Cloud Storage, etc.)."},
  {t:"Avantages GCP",q:"Comment GCP garantit-il la conformité réglementaire ?",o:["GCP n'a aucune certification de conformité","Via des certifications (ISO 27001, SOC 2, PCI DSS) et des contrôles de conformité intégrés","En stockant toutes les données uniquement aux États-Unis","Via un contrat unique valide dans tous les pays"],a:1,e:"Google Cloud détient de nombreuses certifications (ISO 27001, 27017, 27018, SOC 1/2/3, PCI DSS, HIPAA) et fournit des outils pour aider les clients à respecter leurs obligations réglementaires."},
  {t:"Avantages GCP",q:"Qu'est-ce que l'innovation continue de GCP apporte aux utilisateurs ?",o:["Des interfaces qui changent constamment sans raison","Un accès aux mêmes technologies IA/ML que Google utilise en interne","Des prix qui augmentent régulièrement","Des services qui deviennent rapidement obsolètes"],a:1,e:"Google partage son infrastructure et ses technologies d'IA/ML avec ses clients GCP. Les innovations développées pour Google Search, Maps et YouTube sont accessibles via les services cloud."},
  {t:"Avantages GCP",q:"Que signifie 'open source' dans le contexte GCP ?",o:["Des logiciels propriétaires Google uniquement","Des logiciels dont le code source est accessible et modifiable par tous","Des services uniquement disponibles gratuitement","Des API sans documentation"],a:1,e:"Google contribue activement à l'open source (Kubernetes, TensorFlow, Go) et offre des services basés sur des technologies open source, évitant le vendor lock-in et favorisant l'interopérabilité."},
  {t:"Avantages GCP",q:"Qu'est-ce que 'Anthos' permet dans une stratégie multi-cloud ?",o:["La migration forcée vers GCP uniquement","La gestion d'applications sur GCP, on-premise et d'autres clouds depuis une interface unifiée","Un service de stockage multi-cloud","Un protocole de sécurité multi-fournisseur"],a:1,e:"Anthos est une plateforme de gestion d'applications hybrides et multi-cloud de Google, permettant de déployer et gérer des applications conteneurisées sur GCP, AWS, Azure et on-premise."},
  {t:"Avantages GCP",q:"Comment les outils de support GCP sont-ils organisés ?",o:["Un seul niveau de support identique pour tous","Plusieurs niveaux (Basic, Standard, Enhanced, Premium) avec des temps de réponse et services différents","Support uniquement par email pour tous","Support téléphonique uniquement pour les grandes entreprises"],a:1,e:"GCP propose différents niveaux de support : Basic (gratuit, documentation), Developer, Standard, Enhanced et Premium, avec des SLAs de temps de réponse et des services de plus en plus complets."},
  {t:"Avantages GCP",q:"Qu'est-ce que la 'portabilité' dans le contexte GCP ?",o:["La capacité de déplacer physiquement les serveurs","La facilité à migrer des applications entre environnements (cloud, on-premise)","Un service de livraison de matériel","La mobilité des équipes de développement"],a:1,e:"La portabilité désigne la facilité à déplacer des workloads entre environnements. GCP, via Kubernetes et les conteneurs, facilite la portabilité des applications entre cloud et on-premise."},
  {t:"Avantages GCP",q:"Qu'est-ce que la 'gestion centralisée' dans Google Cloud Organizations ?",o:["Centraliser tous les serveurs dans un seul datacenter","Gérer les politiques, accès et facturations de l'ensemble des projets depuis un nœud central","Donner accès administrateur à tous les utilisateurs","Centraliser uniquement la facturation"],a:1,e:"La ressource Organisation dans GCP permet de gérer de façon centralisée toutes les politiques IAM, ressources et facturation pour l'ensemble des projets de l'entreprise depuis un point unique."},
  {t:"Avantages GCP",q:"Qu'est-ce que Cloud Billing dans GCP ?",o:["Un service pour facturer les clients de l'entreprise","La gestion et le suivi des coûts des ressources GCP, avec budgets et alertes","Un protocole de paiement sécurisé","Un outil de comptabilité générale"],a:1,e:"Cloud Billing permet de gérer les comptes de facturation, visualiser et analyser les coûts, créer des budgets avec alertes, et répartir les coûts entre projets et services."},
  {t:"Avantages GCP",q:"Qu'est-ce qu'un 'budget et alerte' dans Cloud Billing ?",o:["Un outil pour limiter automatiquement les dépenses et arrêter les services","Un mécanisme pour définir un seuil de dépenses et recevoir des notifications quand il est atteint","Un contrat de dépenses fixes avec Google","Une limitation technique empêchant tout dépassement"],a:1,e:"Les budgets Cloud Billing permettent de définir des seuils de dépenses et de configurer des alertes automatiques (email, Pub/Sub) lorsque les dépenses réelles ou prévisionnelles dépassent ces seuils."},
  {t:"Avantages GCP",q:"Quelle est la caractéristique principale du modèle 'shared responsibility' de GCP ?",o:["Google est responsable de tout","Le client est responsable de tout","Les responsabilités de sécurité sont partagées entre Google et le client selon le service","Les responsabilités varient aléatoirement"],a:2,e:"Le modèle de responsabilité partagée divise les obligations de sécurité : Google sécurise l'infrastructure cloud, le client sécurise ses données, applications et configurations selon le modèle de service utilisé."},
  {t:"Avantages GCP",q:"Qu'est-ce que 'Cloud Identity' dans GCP ?",o:["Un service de stockage de données d'identité","Un service de gestion des identités et des accès pour les utilisateurs de l'entreprise","Un protocole d'authentification réseau","Un outil de création d'avatars numériques"],a:1,e:"Cloud Identity est un service IDaaS (Identity as a Service) qui permet de gérer les identités des utilisateurs, les groupes et les appareils de l'entreprise, intégré avec IAM et Google Workspace."},
  {t:"Avantages GCP",q:"Que permet le 'Resource Manager' de GCP ?",o:["La gestion du matériel physique des datacenters","La création et gestion hiérarchique des ressources (organisation, dossiers, projets)","Un outil de création de rapports de performance","Un service de provisionnement automatique"],a:1,e:"Cloud Resource Manager permet de créer, gérer et organiser les ressources GCP dans une hiérarchie Organisation > Dossiers > Projets, facilitant l'application de politiques et la gestion des accès."}
];


window.QDATA[2] = [
  {t:"Compute Engine",q:"Qu'est-ce que Google Compute Engine ?",o:["Un service de base de données","Un service de machines virtuelles IaaS sur GCP","Un service d'hébergement de sites web uniquement","Un outil de monitoring des applications"],a:1,e:"Compute Engine est le service IaaS de GCP permettant de créer et gérer des machines virtuelles (instances) sur l'infrastructure mondiale de Google, avec contrôle total sur l'OS et la configuration."},
  {t:"Compute Engine",q:"Qu'est-ce qu'une 'instance préemptible' sur Compute Engine ?",o:["Une VM qui ne peut jamais être arrêtée","Une VM moins chère pouvant être interrompue par Google avec un préavis de 30 secondes","Une VM réservée uniquement aux tests","Une VM sans disque persistant"],a:1,e:"Les instances préemptibles sont des VMs à coût réduit (jusqu'à 80% moins cher) que Google peut arrêter avec 30 secondes de préavis. Idéales pour workloads batch et tolérants aux interruptions."},
  {t:"Compute Engine",q:"Que sont les 'Spot VMs' par rapport aux préemptibles ?",o:["Identiques aux instances préemptibles","Des VMs identiques aux préemptibles mais sans durée maximale de 24h","Des VMs plus chères avec garantie de disponibilité","Des VMs exclusivement pour l'IA/ML"],a:1,e:"Les Spot VMs sont l'évolution des instances préemptibles. Elles offrent les mêmes réductions de prix mais sans la limite de 24 heures, avec le même risque d'interruption selon la disponibilité de capacité."},
  {t:"Compute Engine",q:"Que sont les 'machine types' dans Compute Engine ?",o:["Des types de disques de stockage","Des configurations prédéfinies de CPU et mémoire RAM pour les VMs","Des types de connexions réseau","Des modèles de sécurité pour les instances"],a:1,e:"Les machine types sont des configurations prédéfinies spécifiant le nombre de vCPUs, la quantité de RAM et parfois le type de processeur. Exemples : e2-medium (2 vCPUs, 4GB RAM), n2-standard-4."},
  {t:"Compute Engine",q:"Qu'est-ce qu'un disque persistant dans Compute Engine ?",o:["La mémoire RAM d'une instance","Un stockage réseau durable attaché aux VMs, indépendant de leur cycle de vie","Un disque local temporaire","Un service de sauvegarde automatique"],a:1,e:"Les disques persistants sont des périphériques de stockage réseau durables attachables aux instances Compute Engine. Les données survivent aux redémarrages et peuvent être détachées/réattachées."},
  {t:"Compute Engine",q:"Quelle est la différence entre un disque persistant Standard et SSD ?",o:["Aucune différence de performances","SSD offre des IOPS plus élevés et une latence plus faible que le disque magnétique Standard","Standard est plus rapide en lecture, SSD en écriture","SSD est moins cher que Standard"],a:1,e:"Les disques SSD persistants offrent des performances bien supérieures (IOPS et débit) avec une latence plus faible, adaptés aux bases de données. Les disques Standard sont plus économiques pour les accès séquentiels."},
  {t:"Compute Engine",q:"Qu'est-ce que l'autoscaling dans Compute Engine ?",o:["La mise à jour automatique de l'OS des VMs","L'ajout ou suppression automatique de VMs selon la charge (CPU, requêtes)","La migration automatique entre régions","La sauvegarde automatique des données"],a:1,e:"L'autoscaling permet aux groupes d'instances gérés (MIGs) d'ajuster automatiquement le nombre de VMs selon des métriques (CPU, requêtes HTTP, métriques personnalisées) pour optimiser coûts et performances."},
  {t:"Compute Engine",q:"Que sont les 'Managed Instance Groups' (MIGs) ?",o:["Des groupes de projets GCP","Des groupes de VMs identiques gérées comme une unité pour la haute disponibilité et l'autoscaling","Des groupes de règles de pare-feu","Des groupes d'utilisateurs IAM"],a:1,e:"Les MIGs sont des groupes de VMs identiques basées sur un modèle d'instance. Ils offrent autoscaling, réparation automatique, mises à jour progressives et distribution sur plusieurs zones."},
  {t:"Compute Engine",q:"Qu'est-ce qu'un 'snapshot' de disque dans GCP ?",o:["Une copie en lecture seule et incrémentielle d'un disque persistant","Une sauvegarde complète de toute la région","Une image d'instance identique à une VM existante","Un type de stockage temporaire"],a:0,e:"Les snapshots sont des sauvegardes incrémentilles et cohérentes des disques persistants, stockées dans Cloud Storage. Ils permettent de restaurer des disques ou créer de nouvelles instances."},
  {t:"Compute Engine",q:"Qu'est-ce qu'une 'machine image' dans Compute Engine ?",o:["Un fichier image pour les applications web","Une ressource contenant toute la configuration d'une VM pour créer des instances identiques","Un type de snapshot de disque","Un modèle de réseau virtuel"],a:1,e:"Une machine image capture toute la configuration d'une instance (disques, métadonnées, réseau, permissions), permettant de créer des instances identiques ou de restaurer une instance."},
  {t:"Cloud Storage",q:"Qu'est-ce que Google Cloud Storage ?",o:["Un service de base de données relationnelle","Un service de stockage d'objets unifié pour données non structurées","Un service de stockage de fichiers hiérarchique","Un disque dur virtuel pour VMs"],a:1,e:"Cloud Storage est un service de stockage d'objets hautement disponible et durable pour stocker n'importe quel type de données (fichiers, images, vidéos, backups) sans limite de capacité."},
  {t:"Cloud Storage",q:"Qu'est-ce qu'un 'bucket' dans Cloud Storage ?",o:["Un serveur de fichiers","Un conteneur de niveau supérieur organisant les objets dans Cloud Storage","Un type de disque persistant","Une partition réseau"],a:1,e:"Un bucket est le conteneur de base dans Cloud Storage. Chaque objet (fichier) est stocké dans un bucket. Les buckets ont un nom unique globalement, une localisation et une classe de stockage."},
  {t:"Cloud Storage",q:"Quelle classe de stockage Cloud Storage est optimale pour les données accédées fréquemment ?",o:["Coldline","Archive","Nearline","Standard"],a:3,e:"La classe Standard est optimisée pour les données accédées fréquemment. Elle offre les meilleures performances d'accès mais au coût de stockage le plus élevé."},
  {t:"Cloud Storage",q:"Pour quels types de données la classe 'Coldline' est-elle recommandée ?",o:["Données accédées plusieurs fois par mois","Données accédées environ une fois par an","Données de sauvegarde critique accédées très rarement (moins d'une fois par an)","Données de streaming vidéo"],a:2,e:"Coldline est conçu pour les données rarement accédées, typiquement moins d'une fois par an (archives légales, conformité). Coût de stockage très bas mais frais d'accès et durée minimale de 90 jours."},
  {t:"Cloud Storage",q:"Qu'est-ce que la 'durabilité 99,999999999%' (11 nines) de Cloud Storage ?",o:["La garantie que les données sont toujours accessibles","La probabilité qu'une donnée stockée ne sera pas perdue sur une période donnée","La vitesse de téléchargement garantie","Le pourcentage de disponibilité du service"],a:1,e:"La durabilité 11 nines signifie qu'il y a une probabilité extrêmement faible (moins de 1 sur 100 milliards) qu'un objet stocké dans Cloud Storage soit perdu, grâce à la redondance géographique."},
  {t:"Cloud Storage",q:"Qu'est-ce que le 'versioning' d'objets dans Cloud Storage ?",o:["La compression automatique des fichiers","La conservation des versions précédentes d'un objet lors de modifications","La mise à jour automatique des métadonnées","La réplication dans plusieurs régions"],a:1,e:"Le versioning d'objets conserve toutes les versions d'un objet lors de modifications ou suppressions. Permet de récupérer des versions antérieures et protège contre les suppressions accidentelles."},
  {t:"Cloud Storage",q:"Comment Cloud Storage gère-t-il le chiffrement des données ?",o:["Le chiffrement est optionnel et payant","Les données sont chiffrées par défaut au repos avec AES-256","Le chiffrement nécessite une configuration manuelle","Seules les données en transit sont chiffrées"],a:1,e:"Cloud Storage chiffre automatiquement toutes les données au repos avec AES-256 et en transit avec TLS, sans frais supplémentaires et sans configuration requise. Les clés sont gérées par Google."},
  {t:"Cloud Storage",q:"Qu'est-ce que les 'Object Lifecycle Policies' dans Cloud Storage ?",o:["Des règles de sécurité pour les accès aux objets","Des règles automatisant la transition des objets entre classes de stockage ou leur suppression","Un système de versioning avancé","Des politiques de réplication géographique"],a:1,e:"Les politiques de cycle de vie permettent d'automatiser la transition des objets entre classes de stockage (ex: Standard → Nearline après 30 jours) ou leur suppression après une durée définie."},
  {t:"Cloud Storage",q:"Qu'est-ce que la 'cohérence forte' de Cloud Storage ?",o:["Les données lues sont toujours identiques à celles écrites (pas de lecture de données périmées)","Les données peuvent parfois être obsolètes après une écriture","Une garantie de performances uniformes","Un accord de niveau de service de disponibilité"],a:0,e:"Cloud Storage offre une cohérence forte (strong consistency) pour toutes les opérations. Après une écriture réussie, toute lecture retourne immédiatement les données les plus récentes."},
  {t:"Cloud Storage",q:"Comment accéder aux objets Cloud Storage depuis Internet ?",o:["Uniquement via la Console GCP","Via des URLs publiques ou signées, l'API REST, gsutil ou les bibliothèques clientes","Uniquement via VPN privé","Uniquement depuis des VMs sur GCP"],a:1,e:"Cloud Storage est accessible via URLs HTTPS publiques (pour objets publics), URLs signées temporaires, l'API REST, l'outil CLI gsutil, ou les bibliothèques clientes dans plusieurs langages."},
  {t:"Réseau VPC",q:"Qu'est-ce qu'un VPC (Virtual Private Cloud) dans GCP ?",o:["Un fournisseur de cloud privé concurrent","Un réseau virtuel isolé dans GCP pour héberger les ressources de façon sécurisée","Un service de VPN inter-entreprises","Un type de machine virtuelle sécurisée"],a:1,e:"Un VPC est un réseau virtuel logiquement isolé dans GCP. Il permet de définir la topologie réseau, les plages IP, les règles de pare-feu et de contrôler les flux de communication entre ressources."},
  {t:"Réseau VPC",q:"Quelle est la caractéristique unique du VPC GCP par rapport à d'autres clouds ?",o:["Il ne supporte qu'une seule région","Il est global : un VPC peut s'étendre sur plusieurs régions sans configuration supplémentaire","Il est limité à une seule zone","Il nécessite une adresse IP publique pour chaque ressource"],a:1,e:"Le VPC GCP est global par nature : un seul VPC peut avoir des sous-réseaux dans plusieurs régions du monde. Cela simplifie la connectivité mondiale sans nécessiter de peering complexe."},
  {t:"Réseau VPC",q:"Qu'est-ce qu'un 'sous-réseau' (subnet) dans un VPC GCP ?",o:["Un VPC secondaire","Une partition régionale d'un VPC avec une plage d'adresses IP définie","Une connexion entre deux VPCs","Un groupe de règles de pare-feu"],a:1,e:"Un sous-réseau est une partition régionale d'un VPC avec une plage CIDR spécifique. Les ressources (VMs, containers) créées dans une région sont associées au sous-réseau de cette région."},
  {t:"Réseau VPC",q:"Qu'est-ce que Cloud Firewall (règles de pare-feu VPC) ?",o:["Un service antivirus pour les VMs","Des règles contrôlant le trafic réseau entrant et sortant des instances","Un protocole de chiffrement réseau","Un service de détection d'intrusion"],a:1,e:"Les règles de pare-feu VPC contrôlent le trafic réseau permettant ou refusant les connexions vers/depuis les instances basé sur le protocole, port, IP source/destination et tags réseau."},
  {t:"Réseau VPC",q:"Qu'est-ce que le 'VPC Peering' dans GCP ?",o:["Une connexion entre un VPC GCP et un réseau on-premise","Une connexion réseau privée entre deux VPCs permettant l'échange de trafic","Un service de surveillance réseau","Un protocole de routage dynamique"],a:1,e:"Le VPC Peering établit une connexion réseau privée entre deux VPCs (même organisation ou projets différents), permettant l'échange de trafic sans passer par Internet ou VPN."},
  {t:"Réseau VPC",q:"Qu'est-ce que Cloud VPN ?",o:["Un VPN pour les utilisateurs mobiles","Un service établissant un tunnel chiffré entre un réseau on-premise et GCP via Internet","Un service de réseau privé interne à GCP","Un protocole de chiffrement de stockage"],a:1,e:"Cloud VPN crée des tunnels IPsec chiffrés entre l'infrastructure on-premise et GCP via Internet public, permettant une connectivité sécurisée sans infrastructure dédiée. Convient aux besoins de bande passante modérés."},
  {t:"Réseau VPC",q:"Quelle est la différence entre Cloud VPN et Cloud Interconnect ?",o:["Ils sont identiques","Cloud VPN utilise Internet public chiffré, Cloud Interconnect fournit une connexion physique dédiée à GCP","Cloud VPN est plus fiable que Cloud Interconnect","Cloud Interconnect utilise une connexion sans fil"],a:1,e:"Cloud VPN utilise des tunnels IPsec sur Internet public (bande passante limitée, latence variable). Cloud Interconnect est une connexion physique dédiée haute performance (jusqu'à 100 Gbps) via un partenaire."},
  {t:"Réseau VPC",q:"Qu'est-ce que Cloud Load Balancing ?",o:["Un service de compression de données","Un service distribuant le trafic entre plusieurs instances pour haute disponibilité et performances","Un outil d'équilibrage des coûts entre projets","Un service de routage DNS uniquement"],a:1,e:"Cloud Load Balancing distribue le trafic entre plusieurs instances VM ou services, offrant haute disponibilité, autoscaling et détection des pannes. Disponible en versions HTTP(S), TCP, UDP, global et régional."},
  {t:"Réseau VPC",q:"Qu'est-ce que Cloud DNS dans GCP ?",o:["Un service de détection de malwares réseau","Un service DNS géré haute disponibilité pour publier des noms de domaine","Un protocole de chiffrement DNS","Un service de gestion des certificats SSL"],a:1,e:"Cloud DNS est un service DNS géré scalable et fiable (SLA 100%) permettant de publier et gérer les enregistrements DNS, héberger des zones DNS publiques et privées intégrées aux VPCs."},
  {t:"Réseau VPC",q:"Que fait Cloud NAT (Network Address Translation) ?",o:["Convertit des noms de domaine en adresses IP","Permet aux instances sans IP publique d'accéder à Internet de façon sécurisée","Chiffre le trafic réseau interne","Crée des tunnels VPN automatiquement"],a:1,e:"Cloud NAT permet aux instances VM sans adresses IP externes d'accéder à Internet (mises à jour, APIs externes) sans exposer directement les instances, améliorant la sécurité."},
  {t:"Réseau VPC",q:"Qu'est-ce que le 'réseau Premium Tier' dans GCP ?",o:["Un réseau uniquement pour les clients Premium GCP","L'utilisation du réseau mondial privé de Google pour router le trafic avec performances optimales","Un réseau plus cher sans bénéfice particulier","Un réseau uniquement disponible en Amérique du Nord"],a:1,e:"Le Premium Tier route le trafic via le réseau mondial privé de Google, offrant des latences plus faibles et une fiabilité supérieure. Le Standard Tier utilise l'Internet public, à coût inférieur."},
  {t:"App Engine",q:"Qu'est-ce que Google App Engine ?",o:["Un moteur de recherche d'applications","Une plateforme PaaS pour développer et héberger des applications web scalables sans gérer l'infrastructure","Un service IaaS de machines virtuelles","Un outil de débogage d'applications"],a:1,e:"App Engine est une plateforme PaaS (Platform as a Service) entièrement gérée permettant de déployer des applications web et APIs sans se soucier de l'infrastructure sous-jacente, avec autoscaling automatique."},
  {t:"App Engine",q:"Quelle est la différence entre App Engine Standard et Flexible ?",o:["Standard est plus cher que Flexible","Standard utilise des environnements sandbox avec scaling rapide, Flexible utilise des conteneurs Docker sur des VMs","Flexible ne supporte que Python","Standard ne supporte pas les requêtes HTTP"],a:1,e:"App Engine Standard utilise des runtimes sandbox avec démarrage rapide et scaling à zéro. Flexible utilise des conteneurs Docker sur des VMs, offrant plus de flexibilité mais avec un minimum d'une instance."},
  {t:"App Engine",q:"Qu'est-ce que le 'traffic splitting' dans App Engine ?",o:["La division de la bande passante réseau","La distribution du trafic entre différentes versions d'une application pour déploiements progressifs","Une technique de compression de données","Un protocole de réseau pour applications mobiles"],a:1,e:"Le traffic splitting permet de diriger différents pourcentages du trafic vers différentes versions d'une application App Engine, facilitant les déploiements canary, les tests A/B et les rollouts progressifs."},
  {t:"Cloud Run",q:"Qu'est-ce que Google Cloud Run ?",o:["Un service de gestion des VM","Un service serverless pour exécuter des conteneurs sans gérer l'infrastructure","Un outil de déploiement de code source","Un service de compilation de code"],a:1,e:"Cloud Run est une plateforme serverless permettant d'exécuter des conteneurs stateless. Elle gère automatiquement l'infrastructure, scale de 0 à N selon la demande et facture uniquement à l'utilisation."},
  {t:"Cloud Run",q:"Quel est l'avantage du 'scale to zero' de Cloud Run ?",o:["Les applications ne peuvent jamais être arrêtées","Aucun coût lorsque l'application ne reçoit pas de trafic","Les performances sont meilleures à zéro instance","La sécurité est améliorée sans instances"],a:1,e:"Le scale to zero signifie que Cloud Run réduit les instances à 0 quand il n'y a pas de trafic, évitant les coûts d'idle. Quand une requête arrive, une nouvelle instance démarre rapidement."},
  {t:"Cloud Run",q:"Quelle est la différence entre Cloud Run et Cloud Functions ?",o:["Elles sont identiques","Cloud Run exécute des conteneurs (applications complètes), Cloud Functions exécute des fonctions courtes","Cloud Functions supporte les conteneurs, pas Cloud Run","Cloud Run est uniquement pour les microservices"],a:1,e:"Cloud Run exécute des conteneurs avec applications complètes, requêtes HTTP longues et état. Cloud Functions exécute des fonctions légères déclenchées par des événements avec des limites de temps strictes."},
  {t:"Cloud Functions",q:"Qu'est-ce que Google Cloud Functions ?",o:["Un service de gestion des fonctions IAM","Une plateforme FaaS serverless pour exécuter du code en réponse à des événements sans gérer de serveurs","Un service de création de fonctions SQL","Un outil d'optimisation du code"],a:1,e:"Cloud Functions est une plateforme FaaS (Function as a Service) serverless permettant d'exécuter du code événementiel (HTTP, Cloud Storage, Pub/Sub, Firestore) sans provisionnement de serveurs."},
  {t:"Cloud Functions",q:"Quels langages sont supportés par Cloud Functions (2nd gen) ?",o:["Uniquement Python et Node.js","Node.js, Python, Go, Java, .NET, Ruby, PHP","Uniquement les langages compilés","Tous les langages via conteneurs personnalisés uniquement"],a:1,e:"Cloud Functions 2nd gen (basé sur Cloud Run) supporte Node.js, Python, Go, Java, .NET, Ruby et PHP avec plusieurs versions de runtimes pour chaque langage."},
  {t:"Cloud Functions",q:"Qu'est-ce qu'un déclencheur (trigger) dans Cloud Functions ?",o:["Une erreur qui arrête une fonction","Un événement qui provoque l'exécution d'une fonction (HTTP, message Pub/Sub, changement de fichier)","Un paramètre de configuration de la fonction","Une limite de temps d'exécution"],a:1,e:"Un trigger est un événement qui provoque l'exécution d'une Cloud Function : requête HTTP, message Pub/Sub, modification dans Cloud Storage, changement Firestore, ou événement d'un autre service GCP."},
  {t:"GKE",q:"Qu'est-ce que Google Kubernetes Engine (GKE) ?",o:["Un service de machine virtuelle classique","Un service géré d'orchestration de conteneurs basé sur Kubernetes","Un outil de déploiement de code source","Un service de monitoring des applications"],a:1,e:"GKE est un service géré d'orchestration de conteneurs utilisant Kubernetes. Google gère le plan de contrôle Kubernetes, laissant aux utilisateurs la gestion des workloads et des nœuds de travail."},
  {t:"GKE",q:"Qu'est-ce que le 'mode Autopilot' de GKE ?",o:["Un mode de déploiement manuel","Un mode entièrement géré où Google configure et gère les nœuds, pods et l'infrastructure automatiquement","Un mode de test uniquement","Un mode réservé aux entreprises Premium"],a:1,e:"GKE Autopilot est un mode d'exploitation entièrement géré où Google gère entièrement l'infrastructure (nœuds, sécurité, mise à l'échelle). Vous ne payez que pour les ressources CPU/mémoire des pods."},
  {t:"GKE",q:"Qu'est-ce que le 'mode Standard' de GKE par rapport à Autopilot ?",o:["Identique à Autopilot","Donne plus de contrôle sur la configuration des nœuds mais nécessite plus de gestion par l'utilisateur","Plus simple à utiliser qu'Autopilot","Plus coûteux sans bénéfice supplémentaire"],a:1,e:"GKE Standard donne un contrôle complet sur la configuration des nœuds de travail (type de machine, OS, réseau), mais l'utilisateur doit gérer les mises à jour, la sécurité et le scaling des nœuds."},
  {t:"GKE",q:"Qu'est-ce que 'Cloud Build' dans GCP ?",o:["Un service de construction de VMs","Un service CI/CD géré pour builder, tester et déployer du code automatiquement","Un outil de compilation de code local","Un service de gestion des dépendances"],a:1,e:"Cloud Build est un service CI/CD entièrement géré qui exécute des builds dans des conteneurs, permet d'automatiser les tests et déploiements, et s'intègre avec les dépôts source et les registres d'images."},
  {t:"GKE",q:"Qu'est-ce qu'Artifact Registry dans GCP ?",o:["Un service de stockage de documents légaux","Un service géré pour stocker, gérer et sécuriser les images de conteneurs et packages","Un registre des services GCP disponibles","Un service d'archivage de logs"],a:1,e:"Artifact Registry est le service de gestion d'artefacts de GCP pour stocker les images Docker, packages Maven, npm, Python et autres artefacts de build, avec contrôle d'accès IAM intégré."},
  {t:"GKE",q:"Quelle est la différence entre GKE et Cloud Run pour les conteneurs ?",o:["Ils sont identiques","GKE offre plus de contrôle pour des architectures complexes, Cloud Run est serverless et plus simple","Cloud Run est uniquement pour les microservices","GKE est uniquement pour les grandes entreprises"],a:1,e:"GKE convient aux architectures conteneurisées complexes nécessitant un contrôle fin. Cloud Run est serverless, idéal pour les conteneurs stateless simples avec scaling automatique et moins de configuration."},
  {t:"GKE",q:"Qu'est-ce que 'Cloud Scheduler' dans GCP ?",o:["Un outil de planification des réunions d'équipe","Un service cron géré pour planifier des tâches automatiques à des intervalles définis","Un service d'ordonnancement des VMs","Un outil d'optimisation des performances"],a:1,e:"Cloud Scheduler est un service cron job entièrement géré permettant d'exécuter des tâches à des intervalles définis (cron expressions). Il peut déclencher des endpoints HTTP, des messages Pub/Sub ou des Cloud Tasks."},
  {t:"GKE",q:"Qu'est-ce que 'Cloud Tasks' dans GCP ?",o:["Un gestionnaire de tâches pour équipes de développement","Un service de gestion de files d'attente de tâches asynchrones","Un outil de suivi des bugs","Un service de planification de réunions"],a:1,e:"Cloud Tasks est un service géré de files d'attente de tâches permettant de gérer l'exécution asynchrone de tâches. Il gère la distribution, la reprise sur erreur et le contrôle du débit."},
  {t:"GKE",q:"Quel service GCP est recommandé pour migrer des VMs vers le cloud ?",o:["Cloud Migration Service","Migrate to Virtual Machines (ex-Velostrata)","VM Transfer Tool","Cloud Lift and Shift"],a:1,e:"Migrate to Virtual Machines (anciennement Velostrata/Migrate for Compute Engine) permet de migrer les VMs depuis des environnements on-premise ou d'autres clouds vers Compute Engine avec un minimum de temps d'arrêt."},
  {t:"GKE",q:"Qu'est-ce que 'Bare Metal Solution' dans GCP ?",o:["Des VMs sans système d'exploitation","Des serveurs physiques dédiés hébergés dans des datacenters Google pour workloads nécessitant du matériel dédié","Un service de gestion de matériel physique client","Un protocole réseau sans abstraction"],a:1,e:"Bare Metal Solution fournit des serveurs physiques dédiés dans les datacenters Google pour des workloads nécessitant un accès direct au matériel (Oracle, SAP HANA) sans virtualisation."}
];


window.QDATA[3] = [
  {t:"BigQuery",q:"Qu'est-ce que BigQuery dans GCP ?",o:["Une base de données relationnelle traditionnelle","Un entrepôt de données serverless et entièrement géré pour l'analyse de grands volumes de données","Un service de stockage d'objets","Un outil de visualisation de données"],a:1,e:"BigQuery est un entrepôt de données (data warehouse) serverless, entièrement géré et hautement scalable, permettant d'analyser des pétaoctets de données avec SQL en quelques secondes."},
  {t:"BigQuery",q:"Quel langage de requête est principalement utilisé dans BigQuery ?",o:["Python","NoSQL","SQL standard (ANSI SQL)","R"],a:2,e:"BigQuery utilise le SQL standard ANSI, familier aux analystes de données. Il supporte également les UDFs (User Defined Functions) en JavaScript et SQL, ainsi que les procédures stockées."},
  {t:"BigQuery",q:"Qu'est-ce que la séparation compute/storage dans BigQuery ?",o:["Le stockage et le calcul sont facturés ensemble","Le calcul et le stockage sont indépendants et scalent séparément, optimisant les coûts","Les données ne peuvent pas être stockées sans calcul actif","Le calcul est gratuit, seul le stockage est facturé"],a:1,e:"BigQuery sépare le stockage (Colossus) du calcul (Dremel). Cela permet de scaler chaque composant indépendamment et de ne payer le calcul que lors des requêtes, optimisant les coûts."},
  {t:"BigQuery",q:"Qu'est-ce que BigQuery ML ?",o:["Un service d'IA séparé de BigQuery","La capacité d'entraîner et déployer des modèles ML directement dans BigQuery avec SQL","Un outil de visualisation pour BigQuery","Un service de migration de données vers BigQuery"],a:1,e:"BigQuery ML permet d'entraîner, évaluer et prédire des modèles de machine learning directement dans BigQuery en utilisant SQL standard, sans déplacer les données vers d'autres services."},
  {t:"BigQuery",q:"Qu'est-ce qu'un 'dataset' dans BigQuery ?",o:["Un fichier de données CSV","Un conteneur organisant les tables et vues dans BigQuery, au sein d'un projet","Un type de requête SQL optimisée","Une partition de données dans une table"],a:1,e:"Un dataset est le conteneur de niveau intermédiaire dans BigQuery (Projet > Dataset > Tables). Il regroupe les tables et vues liées, contrôle l'accès et définit la localisation géographique des données."},
  {t:"BigQuery",q:"Qu'est-ce que le 'partitionnement' de tables dans BigQuery ?",o:["La division physique du matériel de stockage","La division d'une table en segments basés sur une colonne (date, entier) pour optimiser les performances et les coûts","La réplication des données dans plusieurs régions","Le chiffrement par blocs des données"],a:1,e:"Le partitionnement divise une table en partitions basées sur une colonne (date d'ingestion, colonne de date, colonne entière). Les requêtes sur des partitions spécifiques lisent moins de données, réduisant coûts et temps."},
  {t:"BigQuery",q:"Qu'est-ce que le 'clustering' de tables dans BigQuery ?",o:["La distribution des données entre plusieurs régions","L'organisation des données dans les partitions selon des colonnes spécifiées pour optimiser les filtres","La création d'index comme dans une base relationnelle","La compression automatique des données"],a:1,e:"Le clustering organise les données dans les fichiers de stockage selon l'ordre des colonnes de clustering spécifiées. Les requêtes filtrant sur ces colonnes lisent moins de blocs, améliorant performances et coûts."},
  {t:"BigQuery",q:"Quel outil est utilisé pour charger des données dans BigQuery depuis Cloud Storage ?",o:["BigQuery Transfer Service","bq load (CLI) ou via la console BigQuery, depuis Cloud Storage, Sheets, etc.","Cloud Dataflow uniquement","SQL INSERT uniquement"],a:1,e:"BigQuery supporte l'import depuis Cloud Storage (CSV, JSON, Avro, Parquet, ORC), BigQuery Data Transfer Service pour sources SaaS, et aussi via l'API de streaming (insertAll) pour données en temps réel."},
  {t:"BigQuery",q:"Qu'est-ce que BigQuery Data Transfer Service ?",o:["Un service de transfert de données entre régions GCP","Un service automatisant le transfert périodique de données depuis des sources SaaS vers BigQuery","Un outil de migration de bases de données vers BigQuery","Un protocole de transfert de fichiers"],a:1,e:"BigQuery Data Transfer Service automatise le transfert de données depuis des sources SaaS (Google Ads, YouTube, Salesforce) et d'autres clouds vers BigQuery selon des planifications définies."},
  {t:"BigQuery",q:"Qu'est-ce que 'BigQuery Omni' ?",o:["Une interface graphique améliorée pour BigQuery","Une extension permettant d'analyser des données stockées sur AWS ou Azure directement depuis BigQuery","Un service BigQuery dédié aux analyses temps réel","Un outil d'optimisation automatique des requêtes"],a:1,e:"BigQuery Omni est une solution d'analyse multi-cloud permettant d'exécuter des requêtes BigQuery sur des données stockées dans Amazon S3 (AWS) ou Azure Blob Storage sans déplacer les données."},
  {t:"Dataflow",q:"Qu'est-ce que Google Cloud Dataflow ?",o:["Un service de gestion des flux de travail (workflows)","Un service géré de traitement de données en flux (streaming) et par lots (batch) basé sur Apache Beam","Un outil de visualisation des flux de données","Un service de transfert de fichiers entre régions"],a:1,e:"Dataflow est un service d'exécution serverless pour les pipelines Apache Beam, permettant le traitement unifié de données en streaming et en batch avec autoscaling automatique et gestion de l'infrastructure."},
  {t:"Dataflow",q:"Qu'est-ce qu'Apache Beam ?",o:["Un protocole de communication réseau","Un modèle de programmation unifié pour créer des pipelines de traitement de données batch et streaming","Un outil de visualisation de données","Un framework de machine learning"],a:1,e:"Apache Beam est un modèle de programmation open source permettant de définir des pipelines de traitement de données qui fonctionnent indifféremment en mode batch ou streaming sur différents runners (Dataflow, Spark, Flink)."},
  {t:"Dataflow",q:"Quelle est la différence entre traitement 'batch' et 'streaming' ?",o:["Ils sont identiques","Batch traite des données en blocs à intervalles définis, Streaming traite les données en continu au fur et à mesure de leur arrivée","Streaming est plus lent que Batch","Batch est uniquement pour les données structurées"],a:1,e:"Le batch traite des données accumulées à des intervalles planifiés (hourly, daily). Le streaming traite les événements en temps quasi-réel dès leur arrivée, permettant des insights immédiats."},
  {t:"Dataflow",q:"Qu'est-ce que Dataflow Templates ?",o:["Des modèles de facturation pour Dataflow","Des pipelines pré-construits pour cas d'usage courants (PubSub → BigQuery, Datastore → BigQuery)","Des modèles de visualisation de données","Des configurations de réseau pour Dataflow"],a:1,e:"Les Dataflow Templates sont des pipelines Dataflow pré-construits pour des intégrations courantes. Ils permettent de déployer rapidement des workflows sans écrire de code (ex: Pub/Sub to BigQuery, GCS to BigQuery)."},
  {t:"Pub/Sub",q:"Qu'est-ce que Google Cloud Pub/Sub ?",o:["Un service de gestion de publications web","Un service de messagerie asynchrone permettant la communication découplée entre services","Un service de stockage de messages","Un protocole de diffusion de contenu"],a:1,e:"Pub/Sub est un service de messagerie asynchrone et scalable permettant la communication découplée entre producteurs (publishers) et consommateurs (subscribers) via des topics, avec garantie de livraison."},
  {t:"Pub/Sub",q:"Que signifie le modèle 'publish-subscribe' ?",o:["Les éditeurs et abonnés doivent se connaître directement","Les producteurs publient des messages sans savoir qui les consommera, les consommateurs s'abonnent aux topics qui les intéressent","Un modèle de facturation Pub/Sub","Un protocole de communication synchrone"],a:1,e:"Dans le modèle publish-subscribe, les publishers envoient des messages à un topic sans connaître les subscribers. Les subscribers s'abonnent aux topics qui les intéressent et reçoivent les messages de façon découplée."},
  {t:"Pub/Sub",q:"Quels sont les cas d'usage principaux de Pub/Sub ?",o:["Uniquement pour les systèmes IoT","Streaming de données, intégration de services, analytics en temps réel, IoT, notifications push","Exclusivement pour les applications mobiles","Uniquement pour la communication entre microservices dans un même projet"],a:1,e:"Pub/Sub est utilisé pour l'ingestion de données en streaming, l'intégration de services distribués, les pipelines analytics temps réel, les notifications, l'IoT et la communication asynchrone entre microservices."},
  {t:"Pub/Sub",q:"Quelle est la durée maximale de rétention des messages dans Pub/Sub ?",o:["24 heures","7 jours (par défaut 7 jours, configurable jusqu'à 31 jours)","1 heure","30 jours minimum"],a:1,e:"Par défaut, Pub/Sub conserve les messages non acquittés pendant 7 jours. Cette rétention est configurable entre 10 minutes et 31 jours selon les besoins de l'application."},
  {t:"Pub/Sub",q:"Qu'est-ce qu'un abonnement 'push' vs 'pull' dans Pub/Sub ?",o:["Identiques mais avec des noms différents","Pull : le subscriber tire les messages du topic. Push : Pub/Sub envoie les messages à un endpoint HTTPS du subscriber","Push est plus rapide que Pull","Pull est uniquement pour les applications mobiles"],a:1,e:"En mode pull, les abonnés demandent activement les messages. En mode push, Pub/Sub livre les messages à un endpoint HTTPS configuré. Push est idéal pour les applications serverless comme Cloud Run/Cloud Functions."},
  {t:"Pub/Sub",q:"Qu'est-ce que Pub/Sub Lite ?",o:["Une version gratuite de Pub/Sub","Une version à faible coût de Pub/Sub avec des garanties de disponibilité réduites pour des cas à fort volume","Un service de messagerie uniquement synchrone","Une version Pub/Sub pour les appareils IoT uniquement"],a:1,e:"Pub/Sub Lite est une version moins chère de Pub/Sub avec des capacités provisionnées (pas d'autoscaling). Idéal pour les workloads à fort débit avec des exigences de disponibilité moins strictes."},
  {t:"Looker",q:"Qu'est-ce que Looker dans l'écosystème Google Cloud ?",o:["Un service de stockage de données","Une plateforme de BI (Business Intelligence) et d'exploration de données avec modélisation sémantique","Un outil de monitoring des ressources GCP","Un service de migration de bases de données"],a:1,e:"Looker est une plateforme de BI d'entreprise permettant l'exploration, l'analyse et la visualisation de données. Acquise par Google en 2019, elle s'intègre nativement avec BigQuery et les autres services GCP."},
  {t:"Looker",q:"Qu'est-ce que LookML dans Looker ?",o:["Un langage de requête similaire à SQL","Un langage de modélisation sémantique définissant les métriques et dimensions de données pour Looker","Un protocole de communication entre Looker et BigQuery","Un langage de visualisation de données"],a:1,e:"LookML est le langage de modélisation de Looker définissant la logique métier, les métriques, dimensions et relations entre données. Il crée une couche sémantique réutilisable au-dessus des bases de données."},
  {t:"Looker",q:"Qu'est-ce que Looker Studio (anciennement Google Data Studio) ?",o:["Un service de stockage de données structurées","Un outil gratuit de création de tableaux de bord et rapports interactifs connecté aux sources de données GCP","Un IDE pour le développement de requêtes SQL","Un service de gestion des équipes data"],a:1,e:"Looker Studio est un outil gratuit de visualisation permettant de créer des dashboards et rapports interactifs à partir de diverses sources (BigQuery, Google Sheets, Analytics, etc.) sans coder."},
  {t:"Dataproc",q:"Qu'est-ce que Google Cloud Dataproc ?",o:["Un service de traitement de documents PDF","Un service géré pour exécuter des clusters Apache Spark, Hadoop et autres frameworks open source","Un service de migration de données","Un outil de traitement d'images"],a:1,e:"Dataproc est un service géré pour exécuter des clusters Apache Spark, Hadoop, Flink et d'autres outils open source de traitement de données massif, avec démarrage rapide et intégration GCP native."},
  {t:"Dataproc",q:"Quel est l'avantage de Dataproc par rapport à l'auto-gestion d'un cluster Hadoop ?",o:["Dataproc est plus lent mais plus simple","Dataproc démarre des clusters en 90 secondes, scale automatiquement et s'intègre avec les services GCP, sans gestion d'infrastructure","Dataproc est uniquement pour les petits volumes de données","Dataproc ne supporte pas Spark"],a:1,e:"Dataproc démarrage des clusters en moins de 90 secondes (vs heures pour Hadoop on-premise), s'intègre nativement avec GCS, BigQuery, Pub/Sub, scale automatiquement et offre la facturation à la seconde."},
  {t:"Dataproc",q:"Qu'est-ce que 'Dataproc Serverless' ?",o:["Une version de Dataproc sans données","Un mode permettant d'exécuter des jobs Spark sans provisionner de cluster, avec gestion automatique des ressources","Un service Dataproc uniquement pour les tests","Un protocole sans serveur pour Hadoop"],a:1,e:"Dataproc Serverless permet d'exécuter des workloads Spark sans créer ni gérer de clusters. Les ressources sont provisionnées automatiquement pour chaque job et libérées après son exécution."},
  {t:"Cloud Composer",q:"Qu'est-ce que Google Cloud Composer ?",o:["Un service de composition musicale pour les développeurs","Un service géré d'orchestration de workflows basé sur Apache Airflow","Un outil de composition de requêtes SQL","Un service de composition d'images IA"],a:1,e:"Cloud Composer est un service d'orchestration de workflows entièrement géré basé sur Apache Airflow. Il permet de créer, planifier et surveiller des pipelines de données complexes avec des DAGs Python."},
  {t:"Cloud Composer",q:"Qu'est-ce qu'un DAG (Directed Acyclic Graph) dans Cloud Composer/Airflow ?",o:["Un type de base de données orientée graphe","La définition d'un workflow sous forme de graphe dirigé acyclique représentant les tâches et leurs dépendances","Un protocole réseau de routage","Un outil de visualisation de données"],a:1,e:"Un DAG est la représentation en Python d'un workflow dans Airflow/Composer. Il définit un ensemble de tâches et leurs dépendances sous forme d'un graphe orienté sans cycle."},
  {t:"Cloud Composer",q:"Dans quel cas utiliser Cloud Composer plutôt que Cloud Workflows ?",o:["Pour des workflows très simples","Pour des pipelines de données complexes avec de nombreuses dépendances, Python natif et intégrations avec des outils data","Pour des workflows HTTP uniquement","Pour des tâches planifiées simples"],a:1,e:"Cloud Composer/Airflow est adapté aux pipelines de données complexes avec logique Python sophistiquée, nombreuses intégrations data (Spark, BigQuery, Dataflow) et communauté open source Airflow."},
  {t:"Data Architecture",q:"Qu'est-ce qu'un 'data lake' ?",o:["Un lac de données physique","Un dépôt centralisé stockant des données brutes dans leur format natif, structurées et non structurées","Une base de données uniquement pour les données structurées","Un service cloud de stockage premium"],a:1,e:"Un data lake est un dépôt centralisé permettant de stocker des données structurées, semi-structurées et non structurées à grande échelle dans leur format natif, pour analyse future (ex: Cloud Storage comme data lake)."},
  {t:"Data Architecture",q:"Quelle est la différence entre data lake et data warehouse ?",o:["Ils sont identiques","Data lake stocke des données brutes pour exploration future, data warehouse stocke des données structurées et transformées pour analyse directe","Data warehouse est plus grand qu'un data lake","Data lake est uniquement pour les données temps réel"],a:1,e:"Un data lake stocke des données brutes diverses (structurées, semi-structurées, non structurées) pour une utilisation future flexible. Un data warehouse (comme BigQuery) stocke des données transformées et structurées pour l'analyse BI."},
  {t:"Data Architecture",q:"Qu'est-ce qu'un pipeline ETL (Extract, Transform, Load) ?",o:["Un protocole de chiffrement des données","Un processus extrayant des données sources, les transformant et les chargeant dans une destination","Un type de connexion réseau","Un outil d'automatisation de tests"],a:1,e:"ETL est un processus d'intégration de données : Extract (extraire depuis sources), Transform (nettoyer, normaliser, enrichir), Load (charger dans la destination comme BigQuery). Dataflow et Dataproc sont utilisés pour ETL sur GCP."},
  {t:"Data Architecture",q:"Qu'est-ce que le 'streaming analytics' ?",o:["L'analyse de données de streaming vidéo uniquement","L'analyse de données en temps réel au fur et à mesure de leur génération","L'analyse de données musicales","L'analyse de fichiers de grande taille par streaming"],a:1,e:"Le streaming analytics traite et analyse des données en temps réel au fur et à mesure de leur génération (logs d'applications, transactions, IoT). Sur GCP : Pub/Sub → Dataflow → BigQuery."},
  {t:"Data Architecture",q:"Qu'est-ce que 'Data Catalog' dans GCP ?",o:["Un catalogue produit pour GCP Marketplace","Un service de découverte, gestion des métadonnées et gouvernance des données de l'entreprise","Un registre de datasets publics","Un outil de catalogage des APIs"],a:1,e:"Data Catalog (Dataplex Data Catalog) est un service de gestion des métadonnées permettant la découverte, compréhension et gouvernance des données en annotant, taggant et cataloguant les ressources de données GCP."},
  {t:"Data Architecture",q:"Qu'est-ce que Dataplex dans GCP ?",o:["Un service de traitement de données graphiques","Une plateforme de gestion intelligente des données pour organiser, sécuriser et gouverner les données distribuées","Un type de data warehouse","Un service de migration de bases de données"],a:1,e:"Dataplex est une plateforme de gestion intelligente des données permettant de découvrir, gérer, surveiller et gouverner des données distribuées sur GCP (BigQuery, Cloud Storage) de façon centralisée."},
  {t:"Data Architecture",q:"Qu'est-ce que Firestore dans GCP ?",o:["Un service de stockage de fichiers","Une base de données NoSQL orientée documents, serverless et scalable pour applications web et mobiles","Un service de gestion des certificats","Un service de stockage d'objets alternatif à Cloud Storage"],a:1,e:"Firestore (anciennement Cloud Datastore) est une base de données NoSQL orientée documents, serverless, scalable et en temps réel. Idéale pour les applications web et mobiles avec synchronisation en temps réel."},
  {t:"Data Architecture",q:"Qu'est-ce que Cloud Bigtable dans GCP ?",o:["Un système de fichiers distribué","Une base de données NoSQL colonnes-wide scale pour données analytiques et opérationnelles à très haut débit","Un service de petites bases de données","Un outil de visualisation de données tabulaires"],a:1,e:"Cloud Bigtable est une base de données NoSQL colonnes-wide hautement performante, scalable à des pétaoctets. Idéale pour les workloads à fort débit (séries temporelles, IoT, analytics, AdTech) avec latences sub-millisecondes."},
  {t:"Data Architecture",q:"Qu'est-ce que Cloud Spanner dans GCP ?",o:["Un service de gestion de clés cryptographiques","Une base de données relationnelle distribuée mondialement, scalable horizontalement et fortement cohérente","Un service de sauvegarde des données","Un outil d'optimisation des requêtes SQL"],a:1,e:"Cloud Spanner est une base de données relationnelle distribuée mondialement, unique en son genre, combinant la cohérence forte des bases SQL traditionnelles avec la scalabilité horizontale des bases NoSQL."},
  {t:"Data Architecture",q:"Qu'est-ce que Cloud SQL dans GCP ?",o:["Un service de requêtes SQL serverless","Un service de bases de données relationnelles gérées (MySQL, PostgreSQL, SQL Server)","Un outil de requêtes sur Cloud Storage","Un service de migration SQL vers NoSQL"],a:1,e:"Cloud SQL est un service de bases de données relationnelles entièrement géré supportant MySQL, PostgreSQL et SQL Server. Google gère les sauvegardes, mises à jour, réplication et disponibilité."},
  {t:"Data Architecture",q:"Quand utiliser Bigtable vs BigQuery ?",o:["Ils sont interchangeables","Bigtable pour les workloads opérationnels à faible latence et fort débit, BigQuery pour les analyses SQL complexes sur de grands volumes","BigQuery pour toutes les opérations","Bigtable est uniquement pour les données structurées"],a:1,e:"Bigtable est optimisé pour les accès opérationnels à faible latence (ms) et fort débit (millions d'ops/sec). BigQuery est optimisé pour les requêtes analytiques SQL complexes sur des pétaoctets de données."},
  {t:"Data Architecture",q:"Qu'est-ce que Memorystore dans GCP ?",o:["Un service de gestion de la mémoire des VMs","Un service de cache en mémoire géré pour Redis et Memcached","Un service de stockage de fichiers temporaires","Un outil d'optimisation de la mémoire des applications"],a:1,e:"Memorystore est un service de cache en mémoire entièrement géré pour Redis et Memcached. Il offre des latences sub-millisecondes pour les cas d'usage comme le caching de sessions, les classements et les queues."},
  {t:"Data Architecture",q:"Qu'est-ce que Database Migration Service (DMS) ?",o:["Un service de migration de fichiers entre buckets","Un service géré pour migrer des bases de données vers Google Cloud avec un minimum de temps d'arrêt","Un service de gestion des versions de schémas","Un outil de synchronisation de données en temps réel"],a:1,e:"Database Migration Service facilite la migration de bases de données (MySQL, PostgreSQL, Oracle) vers Cloud SQL, Cloud Spanner ou AlloyDB sur GCP avec une migration à état minimal ou continu (CDC)."},
  {t:"Analytics GCP",q:"Qu'est-ce que Google Analytics 4 (GA4) et son intégration BigQuery ?",o:["Un outil uniquement pour les sites e-commerce","Une plateforme d'analyse web/app s'intégrant nativement avec BigQuery pour des analyses avancées","Un remplaçant de BigQuery","Un service GCP séparé sans lien avec Analytics"],a:1,e:"GA4 peut exporter automatiquement toutes les données brutes d'événements vers BigQuery, permettant des analyses SQL avancées, des jointures avec d'autres données et des modèles ML sur les comportements utilisateurs."},
  {t:"Analytics GCP",q:"Qu'est-ce que Looker Studio Pro ?",o:["Une version identique à Looker Studio gratuit","Une version payante de Looker Studio avec fonctionnalités d'entreprise (gouvernance, partage, SLA)","Un outil distinct de Looker Studio","Une offre Looker Studio pour les développeurs"],a:1,e:"Looker Studio Pro est la version payante offrant des fonctionnalités d'entreprise : gouvernance des ressources, partage sécurisé dans l'organisation, accès à l'API et support SLA."},
  {t:"Analytics GCP",q:"Qu'est-ce que le service 'Connected Sheets' dans BigQuery ?",o:["Un service de connexion de feuilles de calcul entre elles","Une intégration permettant d'accéder et analyser des données BigQuery directement dans Google Sheets","Un service de partage de Google Sheets","Un connecteur entre Sheets et Gmail"],a:1,e:"Connected Sheets permet d'analyser des milliards de lignes BigQuery directement dans Google Sheets avec des tableaux croisés dynamiques, graphiques et formules, sans écrire de SQL."},
  {t:"Analytics GCP",q:"Qu'est-ce qu'un 'authorized view' dans BigQuery ?",o:["Une vue sécurisée visible uniquement par les administrateurs","Une vue qui peut être partagée avec d'autres projets sans donner accès aux tables sources","Un type de vue matérialisée","Une vue avec des filtres automatiques de sécurité"],a:1,e:"Une authorized view (vue autorisée) dans BigQuery permet de partager les résultats d'une requête avec d'autres projets ou utilisateurs sans leur accorder l'accès direct aux tables sous-jacentes."},
  {t:"Analytics GCP",q:"Qu'est-ce que l'ingestion de données par 'streaming' dans BigQuery ?",o:["Le téléchargement de vidéos dans BigQuery","L'insertion de données en temps réel dans BigQuery via l'API Streaming Inserts (quasi-instantané)","L'importation de fichiers CSV en continu","Le chargement de données depuis Pub/Sub uniquement"],a:1,e:"Le streaming d'ingestion dans BigQuery permet d'insérer des données en temps quasi-réel via l'API insertAll, rendant les données disponibles pour l'analyse en quelques secondes après l'insertion."},
  {t:"Analytics GCP",q:"Qu'est-ce que BigQuery Storage API ?",o:["Une API pour stocker des fichiers dans BigQuery","Une API haute performance pour lire des données BigQuery depuis des frameworks externes (Spark, Pandas) de façon efficace","L'API standard de requêtes BigQuery","Une API de gestion des tables BigQuery"],a:1,e:"BigQuery Storage API permet de lire les données BigQuery directement à haute vitesse via des connexions parallèles, idéal pour les frameworks analytiques (Apache Spark, Arrow/Pandas) accédant à de grands volumes."},
  {t:"Analytics GCP",q:"Qu'est-ce que le 'slot' dans BigQuery et comment il est facturé ?",o:["Un espace de stockage reservé","Une unité de capacité de calcul pour exécuter les requêtes BigQuery, achetée via reservations ou par requête","Une partition de table BigQuery","Un quota d'API gratuit"],a:1,e:"Un slot BigQuery est une unité de calcul virtuelle utilisée pour exécuter les requêtes. En mode à la demande, Google alloue automatiquement des slots. Avec les réservations, vous achetez une capacité fixe de slots."},
  {t:"Analytics GCP",q:"Qu'est-ce que le 'cost-based query optimization' de BigQuery ?",o:["Un service payant d'optimisation des requêtes","L'optimiseur de requêtes intégré qui analyse automatiquement et génère le plan d'exécution le plus efficace","Un outil externe de consultation SQL","Un paramètre de configuration manuel"],a:1,e:"BigQuery inclut un optimiseur de requêtes basé sur les coûts qui analyse la structure des tables, les statistiques et les partitions/clustering pour générer automatiquement le plan d'exécution le plus efficace."}
];


window.QDATA[4] = [
  {t:"Vertex AI",q:"Qu'est-ce que Vertex AI dans GCP ?",o:["Un service de rendu 3D","Une plateforme ML unifiée pour construire, déployer et gérer des modèles d'IA à grande échelle","Un service de visualisation de données","Un outil de développement d'applications mobiles"],a:1,e:"Vertex AI est la plateforme ML unifiée de Google Cloud intégrant tous les outils pour le cycle de vie ML : préparation des données, entraînement, évaluation, déploiement et monitoring des modèles."},
  {t:"Vertex AI",q:"Qu'est-ce que Vertex AI Workbench ?",o:["Un banc de travail physique pour les data scientists","Un environnement de notebooks Jupyter géré pour le développement de ML","Un outil de gestion des datasets","Un service de stockage pour les modèles ML"],a:1,e:"Vertex AI Workbench fournit des notebooks Jupyter gérés et préconfigurés avec les frameworks ML populaires (TensorFlow, PyTorch, Scikit-learn), intégrés avec les services GCP pour le développement ML."},
  {t:"Vertex AI",q:"Qu'est-ce que le 'training' (entraînement) dans Vertex AI ?",o:["La documentation utilisateur","Le processus d'apprentissage du modèle sur les données d'entraînement pour ajuster ses paramètres","Un service de formation en ligne","La compilation du code ML"],a:1,e:"L'entraînement dans Vertex AI est le processus où le modèle apprend des patterns dans les données d'entraînement via des algorithmes d'optimisation (descente de gradient), ajustant ses paramètres pour minimiser l'erreur."},
  {t:"Vertex AI",q:"Qu'est-ce que Vertex AI Model Registry ?",o:["Un registre de modèles commerciaux à acheter","Un dépôt centralisé pour gérer, versionner et gouverner les modèles ML entraînés","Un outil de débogage de modèles","Un service de partage de modèles avec des partenaires"],a:1,e:"Le Model Registry de Vertex AI est un référentiel centralisé permettant de versionner, étiqueter, gérer le cycle de vie et gouverner les modèles ML, facilitant la traçabilité et la reproductibilité."},
  {t:"Vertex AI",q:"Qu'est-ce que 'Vertex AI Endpoints' ?",o:["Des points d'entrée réseau pour les VPCs","Des ressources permettant de déployer des modèles ML pour des prédictions en ligne (REST API)","Des endpoints DNS","Des connexions à des bases de données"],a:1,e:"Les Endpoints Vertex AI hébergent des modèles déployés et exposent une API REST pour les prédictions en ligne (temps réel). Un endpoint peut héberger plusieurs modèles avec du traffic splitting."},
  {t:"Vertex AI",q:"Qu'est-ce que 'Vertex AI Batch Prediction' ?",o:["Des prédictions individuelles en temps réel","L'exécution de prédictions sur de grands volumes de données sans API déployée, de façon asynchrone","Un service de prédiction pour les applications mobiles uniquement","Un outil de test des modèles ML"],a:1,e:"La prédiction batch dans Vertex AI permet d'exécuter des prédictions sur de grands volumes de données (stockées dans BigQuery ou Cloud Storage) de façon asynchrone, sans maintenir un endpoint actif en permanence."},
  {t:"Vertex AI",q:"Qu'est-ce que Vertex AI Feature Store ?",o:["Un magasin de plugins pour Vertex AI","Un service centralisé pour stocker, partager et servir les features ML à basse latence","Un outil de sélection automatique des features","Un service de stockage de modèles ML"],a:1,e:"Vertex AI Feature Store est un service géré pour stocker, partager et servir des features ML. Il garantit la cohérence des features entre l'entraînement et le serving, évitant le 'training-serving skew'."},
  {t:"AutoML",q:"Qu'est-ce qu'AutoML dans GCP ?",o:["Un outil d'automatisation des tâches administratives GCP","Un service permettant de créer des modèles ML personnalisés de haute qualité sans expertise ML approfondie","Un service d'automatisation des déploiements","Un protocole de machine learning automatique"],a:1,e:"AutoML (maintenant intégré dans Vertex AI AutoML) permet de créer des modèles ML personnalisés en soumettant ses données. Google optimise automatiquement l'architecture et les hyperparamètres du modèle."},
  {t:"AutoML",q:"Quels types de données AutoML peut-il traiter ?",o:["Uniquement les données textuelles","Images, vidéos, texte, données tabulaires, et données de traduction","Uniquement les données structurées","Uniquement les images et vidéos"],a:1,e:"AutoML dans Vertex AI supporte plusieurs modalités : images (classification, détection d'objets), vidéos, texte (classification, entités, sentiment), données tabulaires et traduction."},
  {t:"AutoML",q:"Qu'est-ce que le 'Neural Architecture Search' (NAS) dans AutoML ?",o:["Une recherche d'architectures de réseaux locaux","La technique d'AutoML qui explore automatiquement l'espace des architectures de réseaux de neurones pour trouver la meilleure","Un outil de recherche dans les modèles déployés","Un algorithme de sécurité réseau"],a:1,e:"Le NAS est la technologie clé d'AutoML permettant d'explorer automatiquement des millions d'architectures de réseaux de neurones pour identifier celle offrant les meilleures performances pour une tâche donnée."},
  {t:"APIs IA pré-entraînées",q:"Qu'est-ce que Cloud Vision API ?",o:["Un service de surveillance vidéo","Une API permettant d'analyser des images (labels, faces, texte OCR, objets, contenus inappropriés)","Un service d'optimisation d'images","Un outil de création d'images IA"],a:1,e:"Cloud Vision API analyse des images pour extraire des informations : détection de labels/objets, reconnaissance de visages, OCR (lecture de texte), détection de contenu inapproprié, landmarks et logos."},
  {t:"APIs IA pré-entraînées",q:"Qu'est-ce que Cloud Natural Language API ?",o:["Un service de traduction automatique","Une API analysant le texte pour l'entité, le sentiment, la syntaxe et la classification de contenu","Un service de génération de texte","Un outil de correction orthographique"],a:1,e:"Cloud Natural Language API analyse le texte pour : extraction d'entités (personnes, lieux), analyse de sentiment (positif/négatif), analyse syntaxique, classification de contenu et reconnaissance d'entités avec salience."},
  {t:"APIs IA pré-entraînées",q:"Qu'est-ce que Cloud Translation API ?",o:["Un service d'interprétation simultanée","Une API de traduction automatique supportant plus de 100 langues via des modèles de traduction neurale","Un service de localisation d'applications","Un outil de traduction de code source"],a:1,e:"Cloud Translation API traduit du texte entre plus de 100 langues en utilisant des modèles de traduction neurale (NMT) de haute qualité, avec détection automatique de la langue source."},
  {t:"APIs IA pré-entraînées",q:"Qu'est-ce que Cloud Speech-to-Text API ?",o:["Un service de synthèse vocale (Text-to-Speech)","Une API convertissant l'audio en texte écrit avec reconnaissance de la langue et ponctuation automatique","Un service de traitement audio musical","Un outil de compression audio"],a:1,e:"Cloud Speech-to-Text convertit l'audio en texte écrit pour plus de 125 langues, avec modèles adaptés à différents domaines (téléphonie, médias), ponctuation automatique et diarisation des locuteurs."},
  {t:"APIs IA pré-entraînées",q:"Qu'est-ce que Cloud Text-to-Speech API ?",o:["La même chose que Speech-to-Text","Une API synthétisant du texte en parole naturelle avec des voix Standard et WaveNet","Un service de transcription de texte","Un outil de compression de texte"],a:1,e:"Cloud Text-to-Speech convertit le texte en parole naturelle avec des voix Standard (16kHz) et WaveNet (haute qualité, 24kHz), supportant 40+ langues et voix personnalisables via SSML."},
  {t:"APIs IA pré-entraînées",q:"Qu'est-ce que Cloud Video Intelligence API ?",o:["Un service d'hébergement de vidéos","Une API analysant des vidéos pour extraire labels, détection de tirs, reconnaissance de texte et de logos","Un service d'encodage vidéo","Un outil de compression vidéo"],a:1,e:"Video Intelligence API analyse des vidéos pour : détection de labels et objets, détection de tirs (shot detection), reconnaissance de texte (OCR vidéo), reconnaissance de logos et détection de contenu explicite."},
  {t:"APIs IA pré-entraînées",q:"Qu'est-ce que Document AI dans GCP ?",o:["Un service de stockage de documents","Une plateforme IA pour extraire et structurer des informations depuis des documents (factures, formulaires, contrats)","Un service de création de documents PDF","Un outil de signature électronique"],a:1,e:"Document AI utilise l'IA et le ML pour extraire automatiquement des données structurées depuis des documents non structurés (factures, reçus, formulaires W2, contrats) via des parseurs pré-entraînés et personnalisables."},
  {t:"APIs IA pré-entraînées",q:"Qu'est-ce que Recommendations AI dans GCP ?",o:["Un service de recommandations de services GCP","Un service personnalisant les recommandations de produits pour les sites e-commerce basé sur le comportement utilisateur","Un outil de recommandation d'architecture","Un service de conseil en migration cloud"],a:1,e:"Recommendations AI (maintenant dans Vertex AI Search and Recommendations) permet aux retailers de personnaliser les recommandations de produits en temps réel en utilisant les mêmes modèles que Google."},
  {t:"Gemini",q:"Qu'est-ce que Gemini dans le contexte de Google Cloud ?",o:["Un satellite de communication","La famille de modèles de langage large (LLM) multimodaux de Google, disponibles via Vertex AI","Un service de stockage de données multimédia","Un protocole d'authentification Google"],a:1,e:"Gemini est la famille de modèles d'IA multimodaux de Google (texte, images, audio, code, vidéo). Disponible sur Vertex AI en versions Ultra, Pro, Flash et Nano pour différents cas d'usage."},
  {t:"Gemini",q:"Qu'est-ce que Vertex AI Generative AI Studio ?",o:["Un studio de création vidéo","Un espace de travail pour tester, affiner et déployer des modèles génératifs comme Gemini sur Vertex AI","Un service de génération d'images IA","Un outil de création de présentations IA"],a:1,e:"Generative AI Studio (dans Vertex AI) permet de tester les modèles génératifs (Gemini), créer des prompts, affiner les modèles avec ses données et prototyper des applications d'IA générative."},
  {t:"Gemini",q:"Qu'est-ce que le 'prompt engineering' dans le contexte des LLMs ?",o:["L'ingénierie des logiciels de prompt (software)","L'art de concevoir des instructions (prompts) efficaces pour obtenir les meilleures réponses d'un modèle d'IA","Un langage de programmation pour LLMs","Un outil d'optimisation des modèles"],a:1,e:"Le prompt engineering consiste à concevoir des instructions textuelles (prompts) optimisées pour guider les LLMs vers les réponses souhaitées. Inclut des techniques comme few-shot, chain-of-thought et RAG."},
  {t:"Gemini",q:"Qu'est-ce que le 'fine-tuning' (ajustement fin) d'un modèle ?",o:["L'ajustement de la taille de police du modèle","L'entraînement supplémentaire d'un modèle pré-entraîné sur ses propres données pour le spécialiser","Le déploiement initial d'un modèle","La compression d'un modèle ML"],a:1,e:"Le fine-tuning consiste à continuer l'entraînement d'un modèle pré-entraîné (comme Gemini) sur un dataset spécifique, lui permettant de se spécialiser pour un domaine ou une tâche particulière avec moins de données."},
  {t:"Gemini",q:"Qu'est-ce que la génération augmentée par récupération (RAG) ?",o:["Un protocole de sauvegarde de données","Une technique combinant récupération d'informations pertinentes depuis une base de connaissance avec la génération du LLM pour des réponses précises","Un type de compression de modèles ML","Un service de monitoring des LLMs"],a:1,e:"RAG (Retrieval Augmented Generation) améliore les LLMs en récupérant des informations pertinentes depuis une base de connaissances externe avant de générer une réponse, réduisant les hallucinations et améliorant la précision."},
  {t:"Gemini",q:"Qu'est-ce que 'Vertex AI Search' ?",o:["Un moteur de recherche web","Un service permettant de créer des moteurs de recherche enterprise avec IA, basé sur les données de l'entreprise","Un outil de recherche dans les logs","Un service de recherche de modèles ML"],a:1,e:"Vertex AI Search permet de créer des moteurs de recherche enterprise alimentés par l'IA générative de Google, sur les données propriétaires de l'entreprise (documents, sites web, données structurées)."},
  {t:"MLOps",q:"Qu'est-ce que MLOps ?",o:["Un système d'exploitation pour le ML","L'ensemble des pratiques et outils pour déployer, surveiller et maintenir des modèles ML en production de façon fiable","Un langage de programmation ML","Un protocole de communication entre modèles ML"],a:1,e:"MLOps (Machine Learning Operations) applique les principes DevOps au ML : automatisation des pipelines ML, versioning des modèles, monitoring des performances, détection du drift et réentraînement continu."},
  {t:"MLOps",q:"Qu'est-ce que Vertex AI Pipelines ?",o:["Des pipelines de données réseau","Un service d'orchestration de workflows ML permettant d'automatiser et reproduire les pipelines ML (basé sur Kubeflow Pipelines ou TFX)","Des pipelines de déploiement de code","Un service de gestion des dépendances ML"],a:1,e:"Vertex AI Pipelines est un service d'orchestration de workflows ML qui automatise et reproduit les pipelines d'entraînement et d'évaluation de modèles, basé sur Kubeflow Pipelines ou TFX avec exécution serverless."},
  {t:"MLOps",q:"Qu'est-ce que le 'model monitoring' dans Vertex AI ?",o:["La surveillance du serveur hébergeant le modèle","La surveillance en continu des performances du modèle en production pour détecter la dégradation et les drifts de données","Un outil de débogage de code ML","La surveillance des coûts liés au ML"],a:1,e:"Le model monitoring surveille les modèles déployés pour détecter le 'training-serving skew' (écart entre données d'entraînement et production) et le 'drift' des données d'entrée, déclenchant des alertes."},
  {t:"MLOps",q:"Qu'est-ce que le 'data drift' dans le contexte MLOps ?",o:["Un glissement géologique de données","Le changement progressif de la distribution des données en production par rapport aux données d'entraînement","Une erreur de type dans les données","La perte de données en transit"],a:1,e:"Le data drift est le changement progressif de la distribution statistique des données en production. Si les données de production s'éloignent significativement des données d'entraînement, les performances du modèle se dégradent."},
  {t:"MLOps",q:"Qu'est-ce que l'explicabilité des modèles (Explainable AI) sur Vertex AI ?",o:["La documentation technique des modèles ML","Des outils permettant de comprendre et expliquer les décisions des modèles ML (importances des features, attributions)","Un service de traduction des modèles en langage simple","Un protocole de validation des modèles"],a:1,e:"Vertex AI Explainable AI fournit des explications sur les prédictions des modèles (importances des features, attributions SHAP), aidant à comprendre, déboguer et valider les décisions de l'IA."},
  {t:"MLOps",q:"Qu'est-ce que 'Model Garden' dans Vertex AI ?",o:["Un jardin virtuel généré par IA","Un catalogue de modèles fondamentaux (foundation models) pré-entraînés disponibles pour déploiement et fine-tuning","Un service de création de modèles ML","Un outil de gestion des versions de modèles"],a:1,e:"Model Garden est un catalogue Vertex AI proposant des modèles fondamentaux de Google (Gemini, PaLM, Imagen) et partenaires open source (Llama, Mistral), prêts à être déployés ou affinés."},
  {t:"IA Responsable",q:"Que signifie 'IA responsable' pour Google Cloud ?",o:["Une IA qui répond toujours correctement","L'engagement à développer et utiliser l'IA de façon équitable, interprétable, sécurisée et protectrice de la vie privée","Un service de vérification automatique des modèles","Un protocole de sécurité pour l'IA"],a:1,e:"L'IA responsable chez Google couvre plusieurs principes : équité (pas de biais discriminatoires), interprétabilité, robustesse et sécurité, confidentialité, responsabilité et bénéfice social."},
  {t:"IA Responsable",q:"Qu'est-ce que le 'biais' dans les modèles ML ?",o:["Une erreur de calcul aléatoire","Des résultats systématiquement favorables ou défavorables envers certains groupes dus aux données d'entraînement ou l'algorithme","Une technique d'optimisation","Un paramètre de configuration du modèle"],a:1,e:"Le biais dans les modèles ML désigne des résultats systématiquement discriminatoires envers certains groupes (race, genre, âge). Il peut provenir des données d'entraînement (historical bias) ou de l'algorithme lui-même."},
  {t:"IA Responsable",q:"Qu'est-ce que Vertex AI Model Evaluation ?",o:["Un service d'évaluation des coûts de Vertex AI","Des métriques et outils pour évaluer objectivement les performances des modèles (précision, rappel, F1, AUC) avant déploiement","Un service d'audit des modèles par des tiers","Un outil de test des interfaces utilisateur IA"],a:1,e:"Vertex AI Model Evaluation fournit des métriques automatiques (précision, rappel, AUC, RMSE selon le type de modèle) et des visualisations (matrices de confusion, courbes ROC) pour évaluer les modèles avant déploiement."},
  {t:"IA Responsable",q:"Qu'est-ce que 'What-If Tool' dans Vertex AI ?",o:["Un outil de simulation de scénarios business","Un outil d'analyse interactif pour explorer le comportement des modèles et tester des contre-factuels","Un outil de prévision financière","Un service de test A/B pour les modèles"],a:1,e:"Le What-If Tool (maintenant intégré dans Vertex AI) permet d'explorer visuellement les prédictions du modèle sur des exemples individuels, tester des contre-factuels et analyser l'équité selon différentes sous-populations."},
  {t:"IA Responsable",q:"Qu'est-ce que 'Sensitive Data Protection' dans le contexte ML ?",o:["Un service antivirus pour les modèles ML","Un ensemble de pratiques pour détecter et anonymiser les données sensibles dans les datasets d'entraînement (PII, PHI)","Un protocole de chiffrement des modèles","Un service de classification des données sensibles"],a:1,e:"Dans le contexte ML, la protection des données sensibles implique de détecter et traiter les PII (informations personnelles identifiables) dans les données d'entraînement pour éviter que les modèles mémorisent des informations privées."},
  {t:"IA Responsable",q:"Quelle est la politique de Google sur les usages de l'IA interdits ?",o:["Aucune restriction sur l'utilisation de l'IA","Google interdit les applications IA pour des armes, la surveillance de masse, les violences, et d'autres usages contraires à ses principes","Google interdit uniquement les usages militaires","Google n'a pas de politique d'utilisation acceptable pour l'IA"],a:1,e:"Google a établi des principes d'IA définissant les usages interdits : technologies causant des dommages, armes, surveillance violant les normes, collecte non autorisée de données, et applications contraires aux droits de l'homme."},
  {t:"IA Responsable",q:"Qu'est-ce que la 'gouvernance des données' pour les projets ML ?",o:["La gestion administrative des équipes data","L'ensemble des politiques, processus et contrôles assurant la qualité, sécurité et conformité des données utilisées en ML","Un service GCP de gestion des données","Un outil de versioning des datasets"],a:1,e:"La gouvernance des données ML couvre : la qualité et lineage des données, le contrôle d'accès, la conformité réglementaire (RGPD), le versioning des datasets, l'audit des transformations et la documentation."},
  {t:"IA Responsable",q:"Qu'est-ce que 'Vertex AI Colab Enterprise' ?",o:["Un service de développement web","Un environnement de notebooks Jupyter enterprise sécurisé et gouverné, basé sur Google Colab, intégré dans Vertex AI","Un service de collaboration document","Un outil de partage de modèles ML"],a:1,e:"Colab Enterprise est un environnement de notebooks géré et sécurisé intégré dans Vertex AI, offrant la familiarité de Google Colab avec les contrôles enterprise (IAM, VPC, conformité) pour les équipes data science."},
  {t:"IA Responsable",q:"Qu'est-ce que les 'guardrails' dans le contexte des LLMs ?",o:["Des barrières physiques dans les datacenters","Des contraintes et filtres appliqués aux modèles d'IA pour empêcher les sorties nuisibles, biaisées ou inappropriées","Un type d'architecture de réseau de neurones","Un protocole de sécurité réseau"],a:1,e:"Les guardrails sont des contraintes et filtres (techniques et politiques) appliqués aux modèles d'IA générative pour prévenir les outputs nuisibles, offensants, factuellement incorrects ou contraires aux politiques d'utilisation."},
  {t:"IA Responsable",q:"Qu'est-ce que le 'Model Card' dans le contexte de l'IA responsable ?",o:["Une carte de crédit pour payer les modèles ML","Un document standardisé décrivant les performances, limites, usages prévus et considérations éthiques d'un modèle ML","Un certificat de conformité pour les modèles","Une interface graphique pour les modèles ML"],a:1,e:"Un Model Card est un document standardisé accompagnant un modèle ML qui décrit ses performances sur différentes populations, ses limitations connues, ses usages prévus/non prévus et les considérations éthiques."},
  {t:"IA Responsable",q:"Qu'est-ce que 'Secure AI Framework' de Google ?",o:["Un framework de développement d'applications sécurisées","Un cadre guidant les organisations pour sécuriser leurs systèmes IA contre les menaces spécifiques à l'IA (attaques adversariales, empoisonnement de données)","Un protocole de chiffrement pour les modèles ML","Un service de certification de sécurité IA"],a:1,e:"Le Secure AI Framework (SAIF) de Google est un cadre conceptuel aidant les organisations à intégrer la sécurité dans leur cycle de vie IA, couvrant les menaces spécifiques comme les attaques adversariales et l'injection de prompts."},
  {t:"IA Responsable",q:"Qu'est-ce que l'hallucination dans les LLMs ?",o:["Un bug de visualisation dans l'interface","La tendance des LLMs à générer des informations plausibles mais factuellement incorrectes ou inventées","Une technique d'amélioration des performances","Un type de biais racial dans les modèles"],a:1,e:"L'hallucination est le phénomène où les LLMs génèrent des réponses qui semblent cohérentes mais contiennent des informations factuellement incorrectes ou inventées, car les modèles optimisent la plausibilité linguistique plus que la vérité factuelle."},
  {t:"IA Responsable",q:"Comment Vertex AI aide-t-il à respecter le RGPD dans les projets ML ?",o:["Vertex AI n'a aucun outil RGPD","Via des contrôles de résidence des données, le chiffrement, les accès granulaires IAM, l'anonymisation (Cloud DLP) et les Data Processing Agreements avec Google","En stockant toutes les données en Europe automatiquement","Via un certificat RGPD automatique"],a:1,e:"Vertex AI aide à la conformité RGPD via : la résidence des données configurable, le chiffrement au repos et en transit, les contrôles IAM granulaires, l'intégration avec Cloud DLP pour l'anonymisation et les DPA avec Google."},
  {t:"IA Responsable",q:"Qu'est-ce que 'AI Principles' de Google ?",o:["Les principes de tarification des services IA GCP","Sept objectifs guidant le développement et l'utilisation de l'IA par Google : être utile, juste, sûr, responsable, protecteur de la vie privée, scientifiquement rigoureux et accessible","Un outil de vérification automatique de conformité IA","Un programme de certification IA pour les clients"],a:1,e:"Les 7 principes IA de Google (publiés en 2018) guident tous les développements IA : être utile au niveau social, éviter les biais injustes, être construit et testé pour la sécurité, être responsable, protéger la confidentialité, maintenir l'excellence scientifique et être accessible à tous."},
  {t:"IA Responsable",q:"Qu'est-ce que 'Constitutional AI' dans le contexte des LLMs ?",o:["Un LLM spécialisé en droit constitutionnel","Une approche d'entraînement des LLMs qui leur enseigne un ensemble de principes pour auto-critiquer et réviser leurs réponses","Un service de gouvernance des LLMs","Un protocole de sécurité pour les LLMs"],a:1,e:"Constitutional AI (développé par Anthropic, intégré dans certaines approches) est une méthode où un LLM est entraîné à suivre un ensemble de principes constitutionnels pour auto-critiquer ses réponses et les rendre plus sûres."},
  {t:"IA Responsable",q:"Que signifie 'human-in-the-loop' dans les systèmes ML ?",o:["Un humain qui recopie les données manuellement","L'intégration d'un jugement humain dans le processus ML, notamment pour la vérification des prédictions critiques","Un service de labellisation automatique","Un protocole de communication entre humains et IA"],a:1,e:"'Human-in-the-loop' intègre le jugement humain dans les systèmes ML pour les décisions critiques, la labellisation des données d'entraînement, la correction des erreurs et la validation des prédictions avant action."}
];


window.QDATA[5] = [
  {t:"IAM",q:"Qu'est-ce que Cloud IAM (Identity and Access Management) ?",o:["Un service de gestion des identités externes","Un service contrôlant qui (identité) peut faire quoi (permissions) sur quelles ressources GCP","Un outil de gestion des mots de passe","Un service d'annuaire LDAP"],a:1,e:"Cloud IAM est le service de contrôle d'accès de GCP basé sur le principe 'qui peut faire quoi sur quelle ressource', permettant une gestion granulaire des accès à toutes les ressources GCP."},
  {t:"IAM",q:"Quels sont les trois composants principaux d'une policy IAM ?",o:["Utilisateur, Groupe, Rôle","Principal (qui), Rôle (permissions), Ressource (quoi)","Projet, Service, Ressource","Admin, User, Guest"],a:1,e:"Une policy IAM définit : le principal (membre/identité : compte Google, service account, groupe), le rôle (ensemble de permissions), et la ressource sur laquelle s'applique la policy."},
  {t:"IAM",q:"Quelle est la différence entre rôle de base et rôle prédéfini dans IAM ?",o:["Ils sont identiques","Rôles de base (Owner/Editor/Viewer) donnent des permissions larges sur tout le projet, rôles prédéfinis sont granulaires par service","Les rôles prédéfinis donnent plus de droits","Les rôles de base ne sont plus disponibles"],a:1,e:"Les rôles de base (Owner, Editor, Viewer) accordent des permissions très larges sur toutes les ressources d'un projet. Les rôles prédéfinis sont spécifiques à un service (ex: roles/compute.instanceAdmin) avec des permissions précises."},
  {t:"IAM",q:"Qu'est-ce qu'un 'Service Account' dans GCP ?",o:["Un compte pour les employés du service client","Une identité pour les applications et services (pas des humains) permettant aux ressources GCP de s'authentifier","Un compte de test temporaire","Un compte partagé entre plusieurs utilisateurs"],a:1,e:"Un Service Account est une identité spéciale pour les applications et VMs, permettant aux ressources GCP de s'authentifier et d'appeler d'autres services GCP sans identifiants utilisateur humain."},
  {t:"IAM",q:"Qu'est-ce que le principe du moindre privilège (least privilege) ?",o:["Donner tous les droits à tous les utilisateurs","Accorder uniquement les permissions minimales nécessaires pour accomplir une tâche spécifique","Utiliser uniquement des rôles de base","Ne donner aucun accès par défaut"],a:1,e:"Le principe du moindre privilège consiste à n'accorder à chaque utilisateur ou service que les permissions strictement nécessaires pour accomplir ses tâches, limitant l'impact potentiel d'une compromission."},
  {t:"IAM",q:"Qu'est-ce que l'héritage de policies IAM dans la hiérarchie GCP ?",o:["Chaque ressource a ses propres politiques sans héritage","Les politiques IAM se propagent de l'organisation vers les dossiers, projets et ressources (héritage vers le bas)","L'héritage se fait uniquement entre projets frères","Les politiques du projet remplacent toujours celles de l'organisation"],a:1,e:"Les policies IAM héritent vers le bas : les politiques définies au niveau Organisation s'appliquent à tous les dossiers, les politiques de dossier aux projets enfants, etc. L'union des policies à chaque niveau détermine les accès effectifs."},
  {t:"IAM",q:"Qu'est-ce que la 'deny policy' dans Cloud IAM ?",o:["Une politique refusant l'accès à tous les services","Une politique permettant de refuser explicitement des permissions, même si d'autres rôles les accordent","Un type de service account","Une configuration de pare-feu"],a:1,e:"Les Deny Policies dans Cloud IAM permettent de créer des règles de refus explicites qui ont priorité sur les allow policies, permettant d'interdire des actions spécifiques à des principals même s'ils ont par ailleurs les permissions."},
  {t:"IAM",q:"Qu'est-ce que l'authentification multi-facteurs (MFA) dans GCP ?",o:["Une méthode de cryptage à plusieurs couches","Une exigence de vérification avec plusieurs méthodes (mot de passe + téléphone/clé physique) pour accéder aux ressources","Un service de surveillance multi-régions","Un protocole réseau à plusieurs niveaux"],a:1,e:"L'MFA exige que les utilisateurs fournissent plusieurs formes de vérification (ex: mot de passe + code SMS, ou clé de sécurité physique) avant d'accéder aux ressources, renforçant significativement la sécurité."},
  {t:"IAM",q:"Que fait Cloud Identity-Aware Proxy (IAP) ?",o:["Un proxy réseau pour les VMs","Un service contrôlant l'accès aux applications web via l'identité de l'utilisateur, sans VPN","Un service d'anonymisation des identités","Un outil de gestion des certificats SSL"],a:1,e:"Cloud IAP contrôle l'accès aux applications web et VMs basé sur l'identité et le contexte de l'utilisateur, permettant un accès Zero Trust sécurisé sans nécessiter de VPN pour les applications internes."},
  {t:"IAM",q:"Qu'est-ce que BeyondCorp Enterprise dans GCP ?",o:["Un service cloud pour grandes entreprises uniquement","Une implémentation de Zero Trust Access permettant l'accès sécurisé aux applications sans VPN traditionnel","Un niveau de support Premium","Un service de pare-feu avancé"],a:1,e:"BeyondCorp Enterprise est la solution Zero Trust Access de Google, permettant aux employés d'accéder aux applications d'entreprise de n'importe quel appareil, n'importe où, sans VPN, basé sur l'identité et le contexte."},
  {t:"Cloud Armor",q:"Qu'est-ce que Google Cloud Armor ?",o:["Une protection physique des datacenters Google","Un service de protection DDoS et WAF pour les applications exposées via Cloud Load Balancing","Un service de chiffrement des données","Un service de protection des VMs contre les malwares"],a:1,e:"Cloud Armor est un service de sécurité réseau offrant protection DDoS (Distributed Denial of Service) et WAF (Web Application Firewall) pour les applications web via des policies de sécurité configurables."},
  {t:"Cloud Armor",q:"Qu'est-ce qu'une règle WAF (Web Application Firewall) dans Cloud Armor ?",o:["Une règle de réseau interne","Une règle filtrant le trafic HTTP/S pour bloquer les attaques web (injection SQL, XSS, OWASP Top 10)","Une règle de sauvegarde des données web","Un protocole de compression web"],a:1,e:"Les règles WAF de Cloud Armor filtrent et bloquent les requêtes HTTP/S malveillantes basées sur des signatures d'attaques connues (injection SQL, XSS, traversée de répertoires) selon les règles OWASP Top 10."},
  {t:"Cloud Armor",q:"Qu'est-ce que la 'adaptive protection' de Cloud Armor ?",o:["Une protection adaptée au budget du client","Un système de détection ML qui analyse le trafic pour identifier et suggérer des règles contre les attaques DDoS volumétriques","Une protection qui s'adapte automatiquement à tous les types de menaces","Un service de protection uniquement pour les applications mobiles"],a:1,e:"Adaptive Protection utilise le ML pour analyser le trafic vers les backends protégés par Cloud Armor, détecter les attaques DDoS layer 7 et suggérer automatiquement des règles de protection."},
  {t:"DLP",q:"Qu'est-ce que Cloud DLP (Data Loss Prevention) ?",o:["Un service de prévention de la perte d'énergie électrique","Un service découvrant, classifiant et dépersonnalisant les données sensibles (PII, PHI, PCI) dans les données GCP","Un service de prévention des pertes de données par accident","Un outil de récupération après sinistre"],a:1,e:"Cloud DLP est un service entièrement géré permettant de découvrir, classer et protéger les informations sensibles (PII, PHI, numéros de carte, mots de passe) dans les données stockées ou en transit via détection et dépersonnalisation."},
  {t:"DLP",q:"Quelles techniques Cloud DLP utilise-t-il pour protéger les données sensibles ?",o:["Uniquement la suppression des données sensibles","Pseudonymisation (tokenisation), masquage, redaction, chiffrement préservant le format et bucketing","La compression cryptographique uniquement","Le déplacement des données dans une zone sécurisée"],a:1,e:"Cloud DLP peut transformer les données sensibles via pseudonymisation (tokenisation réversible avec Cloud KMS), masquage, rédaction (suppression), chiffrement préservant le format (FPE) et bucketing de données numériques."},
  {t:"Cloud KMS",q:"Qu'est-ce que Cloud KMS (Key Management Service) ?",o:["Un service de gestion des connaissances (Knowledge Management)","Un service géré de gestion des clés cryptographiques pour chiffrer les données GCP","Un service de gestion des coûts","Un protocole réseau sécurisé"],a:1,e:"Cloud KMS est un service géré permettant de créer, gérer et contrôler les clés de chiffrement utilisées pour protéger les données dans GCP, avec audit trail complet des utilisations des clés."},
  {t:"Cloud KMS",q:"Qu'est-ce que CMEK (Customer-Managed Encryption Keys) ?",o:["Des clés générées automatiquement par Google","Des clés de chiffrement gérées par le client dans Cloud KMS, utilisées pour chiffrer les données dans les services GCP","Des clés partagées entre plusieurs clients","Des clés de chiffrement uniquement pour le stockage"],a:1,e:"CMEK permet aux clients de gérer leurs propres clés de chiffrement dans Cloud KMS et de les utiliser pour chiffrer les données dans les services GCP (BigQuery, GCS, Pub/Sub), offrant un contrôle total sur les clés."},
  {t:"Cloud KMS",q:"Qu'est-ce que Cloud HSM (Hardware Security Module) ?",o:["Un composant matériel de mémoire haute vitesse","Un service de gestion de clés avec des HSMs certifiés FIPS 140-2 Level 3 pour les exigences de conformité strictes","Un service de haute disponibilité pour les serveurs","Un module de supervision matérielle"],a:1,e:"Cloud HSM permet de protéger les clés cryptographiques dans des modules de sécurité matériels certifiés FIPS 140-2 Level 3, offrant le plus haut niveau de protection pour les exigences de conformité strictes."},
  {t:"Security Command Center",q:"Qu'est-ce que Security Command Center (SCC) ?",o:["Un centre de commandement militaire","La plateforme de gestion des risques de sécurité de GCP centralisant les découvertes de sécurité et conformité","Un service de monitoring des performances","Un outil de gestion des certificats SSL"],a:1,e:"Security Command Center est le tableau de bord centralisé de sécurité GCP qui agrège les découvertes de vulnérabilités, mauvaises configurations, menaces et conformité depuis tous les services GCP."},
  {t:"Security Command Center",q:"Qu'est-ce que 'Security Health Analytics' dans SCC ?",o:["Un service d'analyse de la santé des serveurs","Un service détectant automatiquement les mauvaises configurations de sécurité dans les services GCP","Un outil de surveillance de la santé des employés","Un service d'analyse des performances réseau"],a:1,e:"Security Health Analytics dans SCC analyse automatiquement les configurations GCP pour détecter les violations de bonnes pratiques de sécurité (ports ouverts, accès publics non intentionnels, absence de MFA)."},
  {t:"Security Command Center",q:"Qu'est-ce que 'Event Threat Detection' dans SCC ?",o:["Un service de détection d'événements planifiés","Un service utilisant la threat intelligence de Google pour détecter les menaces actives dans les logs GCP","Un service d'analyse des pannes","Un outil de monitoring des changements de configuration"],a:1,e:"Event Threat Detection utilise l'intelligence sur les menaces de Google (threat intel, ML) pour détecter les attaques actives dans les logs GCP : compromissions de comptes, minage de cryptomonnaies, activité malveillante."},
  {t:"Conformité",q:"Qu'est-ce que les 'Assured Workloads' dans GCP ?",o:["Des workloads garantis de fonctionner sans erreur","Un service permettant de configurer les environnements GCP pour répondre à des exigences réglementaires spécifiques (FedRAMP, IL2, etc.)","Des workloads optimisés pour les performances","Un service de garantie de remboursement"],a:1,e:"Assured Workloads permet de configurer les environnements GCP pour se conformer à des exigences réglementaires spécifiques en limitant automatiquement la localisation des données et les accès du personnel Google."},
  {t:"Conformité",q:"Qu'est-ce que le 'Privacy by Design' dans GCP ?",o:["Un service de conception d'interfaces privées","L'intégration de la protection de la vie privée dès la conception des services et systèmes, pas après coup","Un outil de design UX pour applications privées","Un protocole de confidentialité réseau"],a:1,e:"'Privacy by Design' est le principe d'intégrer les exigences de protection de la vie privée dès la conception des systèmes, pas après. GCP l'implémente via des contrôles de confidentialité intégrés dans tous ses services."},
  {t:"Conformité",q:"Qu'est-ce que la résidence des données (data residency) dans GCP ?",o:["La localisation physique du bureau du client","La garantie que les données sont stockées et traitées uniquement dans des régions géographiques spécifiées","La durée de conservation des données","La propriété légale des données"],a:1,e:"La résidence des données permet aux clients de spécifier les régions GCP où leurs données doivent être stockées et traitées, essentiel pour les exigences réglementaires comme le RGPD ou les données sensibles gouvernementales."},
  {t:"Conformité",q:"Qu'est-ce que le programme 'Access Transparency' de Google Cloud ?",o:["Un programme de transparence des prix","Un service fournissant des logs auditables des accès du personnel Google aux données clients","Un service de monitoring des accès des clients","Un programme de certification de transparence"],a:1,e:"Access Transparency génère des logs quasi-temps réel montrant les actions du personnel Google sur les données clients, avec les raisons justifiant l'accès, permettant aux clients de vérifier les accès de leur fournisseur cloud."},
  {t:"Conformité",q:"Qu'est-ce que 'Sovereign Controls' dans GCP ?",o:["Un service de contrôle gouvernemental","Des capacités permettant aux clients de contrôler entièrement l'accès à leurs données, y compris en rendant certaines données inaccessibles aux employés Google","Un service réservé aux gouvernements","Un outil de contrôle des droits de propriété intellectuelle"],a:1,e:"Sovereign Controls (via Assured Workloads et Cloud External Key Manager) permettent aux organisations de maintenir un contrôle souverain sur leurs données dans GCP, avec des options pour que Google ne puisse pas accéder aux clés de chiffrement."},
  {t:"Conformité",q:"Qu'est-ce que Cloud Audit Logs dans GCP ?",o:["Un outil de correction automatique des erreurs","Des journaux d'audit enregistrant les activités administratives, accès aux données et événements système pour tous les services GCP","Un service de compression de logs","Un outil d'analyse des performances"],a:1,e:"Cloud Audit Logs enregistrent automatiquement les activités dans GCP : Admin Activity (qui a fait quoi), Data Access (accès aux données), System Events (actions système automatiques) et Policy Denied (accès refusés)."},
  {t:"Conformité",q:"Qu'est-ce que 'Chronicle SIEM' dans l'écosystème Google Cloud ?",o:["Un service de gestion des chroniques d'entreprise","Une plateforme SIEM (Security Information and Event Management) pour analyser de vastes quantités de logs de sécurité","Un service de sauvegarde des logs historiques","Un outil de gestion des incidents IT classiques"],a:1,e:"Chronicle (maintenant Chronicle Security Operations) est le SIEM de Google, conçu pour ingérer et analyser de très grands volumes de télémétrie de sécurité à la vitesse et à l'échelle de Google."},
  {t:"Conformité",q:"Qu'est-ce que le 'Shared Fate' model de Google Cloud ?",o:["Un service de partage de ressources entre clients","L'approche de Google s'impliquant activement dans la sécurité de ses clients (vs shared responsibility traditionnelle), fournissant outils et guidance","Un programme de partage de revenus","Un modèle de facturation partagée"],a:1,e:"Shared Fate (vs Shared Responsibility) est l'approche de Google s'engageant activement dans les outcomes de sécurité des clients, en fournissant des blueprints, outils, détections et remédiation intégrés plutôt que de seulement définir des responsabilités."},
  {t:"Conformité",q:"Qu'est-ce que la certification ISO 27001 pour GCP ?",o:["Une certification de qualité des logiciels","Une norme internationale de gestion de la sécurité de l'information certifiant les contrôles de sécurité de Google Cloud","Une certification de performance réseau","Une norme de gestion des datacenters"],a:1,e:"ISO 27001 est la norme internationale de référence pour les systèmes de management de la sécurité de l'information (SMSI). La certification GCP confirme que Google implémente les contrôles de sécurité appropriés."},
  {t:"Conformité",q:"Qu'est-ce que SOC 2 Type II dans le contexte GCP ?",o:["Un standard de qualité logicielle","Un rapport d'audit tiers attestant des contrôles de sécurité, disponibilité, intégrité, confidentialité et vie privée de GCP sur une période (typ. 6-12 mois)","Un niveau de support client","Un protocole de communication sécurisée"],a:1,e:"SOC 2 Type II est un rapport d'audit indépendant évaluant les contrôles internes d'un fournisseur de services sur une période définie (généralement 6-12 mois), validant que les contrôles fonctionnent effectivement dans le temps."},
  {t:"Conformité",q:"Qu'est-ce que la conformité PCI DSS pour GCP ?",o:["Un standard de transmission de données informatiques","La certification confirmant que GCP répond aux exigences de sécurité pour le traitement des données de cartes de paiement","Un standard de performance des processeurs","Une certification de qualité des données"],a:1,e:"PCI DSS (Payment Card Industry Data Security Standard) est le standard de sécurité pour les entités traitant des données de cartes de paiement. La conformité GCP permet aux clients de construire des environnements PCI DSS sur GCP."},
  {t:"Conformité",q:"Qu'est-ce que HIPAA dans le contexte GCP ?",o:["Une loi de protection des données européenne","Un règlement américain sur la protection des données de santé (PHI), pour lequel GCP signe des BAA avec les clients","Une certification de performance cloud","Un standard de gestion des systèmes informatiques"],a:1,e:"HIPAA (Health Insurance Portability and Accountability Act) réglemente la protection des données de santé (PHI) aux États-Unis. Google Cloud peut signer des BAA (Business Associate Agreements) avec les clients pour les workloads HIPAA."},
  {t:"Conformité",q:"Qu'est-ce que le RGPD (GDPR) et son impact sur GCP ?",o:["Un règlement uniquement américain sur les données","Le règlement européen général sur la protection des données, imposant des exigences strictes sur le traitement des données des résidents UE","Un standard technique de transmission de données","Un protocole de sécurité réseau européen"],a:1,e:"Le RGPD est le règlement européen sur la protection des données personnelles. GCP propose des contrôles de résidence des données, chiffrement, IAM, DPA et outils pour aider les clients à respecter le RGPD."},
  {t:"Conformité",q:"Qu'est-ce que FedRAMP pour les services cloud US ?",o:["Un protocole réseau fédéral américain","Un programme gouvernemental américain standardisant les évaluations de sécurité des services cloud pour les agences fédérales","Un service cloud réservé aux forces armées","Un certificat de cybersécurité privé"],a:1,e:"FedRAMP (Federal Risk and Authorization Management Program) est un programme US standardisant la sécurité des services cloud pour les agences fédérales. Google Cloud dispose des autorisations FedRAMP pour de nombreux services."},
  {t:"Conformité",q:"Qu'est-ce que 'Cloud External Key Manager' (EKM) ?",o:["Un gestionnaire de clés Cloud KMS standard","Un service permettant d'utiliser des clés de chiffrement hébergées en dehors de GCP (chez un HSM tiers) pour chiffrer les données GCP","Un outil de migration des clés entre services","Un protocole d'échange de clés réseau"],a:1,e:"Cloud EKM permet d'utiliser des clés de chiffrement hébergées dans un système de gestion de clés externe (partenaires HSM tiers comme Thales, Fortanix) pour chiffrer des données dans GCP, offrant une souveraineté complète sur les clés."},
  {t:"Conformité",q:"Qu'est-ce que VPC Service Controls ?",o:["Des règles de pare-feu avancées","Un mécanisme créant un périmètre de sécurité autour des services GCP pour prévenir l'exfiltration de données","Un service de contrôle de la bande passante","Un outil de gestion des politiques réseau"],a:1,e:"VPC Service Controls crée des périmètres de sécurité autour des ressources GCP (BigQuery, GCS, etc.) pour empêcher l'exfiltration de données, même en cas de vol d'identifiants, en limitant les accès aux réseaux autorisés."},
  {t:"Conformité",q:"Qu'est-ce que 'Binary Authorization' dans GCP ?",o:["Un service d'autorisation d'accès binaire","Un service qui permet de déployer uniquement des images de conteneurs qui ont été signées et vérifiées par des processus de confiance","Un système d'authentification à deux facteurs","Un protocole de chiffrement binaire"],a:1,e:"Binary Authorization est un service de contrôle de déploiement qui garantit que seules les images de conteneurs qui ont été vérifiées et signées par des processus de confiance définis (CI/CD) peuvent être déployées sur GKE."},
  {t:"Conformité",q:"Qu'est-ce que Web Security Scanner dans SCC ?",o:["Un outil de surveillance du web","Un service qui scanne automatiquement les applications web App Engine et GCE pour détecter les vulnérabilités OWASP courantes","Un filtre de contenu web","Un service d'indexation web"],a:1,e:"Web Security Scanner (dans SCC) analyse automatiquement les applications web déployées sur App Engine, GCE et GKE pour détecter les vulnérabilités communes : XSS, injection SQL, bibliothèques obsolètes, mauvaises configurations."},
  {t:"Conformité",q:"Qu'est-ce que 'Sensitive Data Protection' (anciennement Cloud DLP) comme service standalone ?",o:["Un antivirus cloud","Un service complet de découverte, classification, anonymisation et protection des données sensibles via des inspecteurs configurables et détecteurs InfoTypes","Un service de compression de données confidentielles","Un outil de gestion des accès aux données sensibles"],a:1,e:"Sensitive Data Protection (renommé depuis Cloud DLP) offre plus de 150 infoType détecteurs, des transformations de données (masquage, tokenisation, chiffrement FPE) et l'intégration avec GCS, BigQuery et Datastore."},
  {t:"Conformité",q:"Qu'est-ce que l'approche 'Zero Trust' en sécurité ?",o:["Un modèle de sécurité ne faisant confiance à aucun trafic réseau, nécessitant vérification continue de l'identité, appareil et contexte pour tout accès","Un modèle de sécurité sans pare-feu","Une approche accordant une confiance totale au réseau interne","Un protocole de cryptographie sans certificat"],a:1,e:"Zero Trust est un modèle de sécurité basé sur le principe 'ne jamais faire confiance, toujours vérifier'. Il exige une vérification continue de l'identité, du contexte et de l'état de l'appareil pour tout accès, indépendamment de la localisation réseau."}
];


window.QDATA[6] = [
  {t:"Google Workspace",q:"Qu'est-ce que Google Workspace ?",o:["Un logiciel bureautique installé localement","Une suite de productivité cloud incluant Gmail, Drive, Docs, Sheets, Meet, Calendar et plus","Un service uniquement pour les développeurs","Un réseau social d'entreprise"],a:1,e:"Google Workspace (anciennement G Suite) est une suite d'outils de productivité et de collaboration cloud incluant Gmail, Drive, Docs, Sheets, Slides, Meet, Calendar, Chat et d'autres applications professionnelles."},
  {t:"Google Workspace",q:"Quelle est la différence entre Google Workspace et les applications Google grand public ?",o:["Aucune différence","Workspace offre des contrôles admin d'entreprise, stockage dédié, SLA, conformité, support et pas de publicités","Workspace est moins fonctionnel","Les applications grand public ont plus de fonctionnalités"],a:1,e:"Google Workspace ajoute aux outils Google grand public : console d'administration centralisée, stockage illimité (selon plan), SLA 99.9%, conformité (HIPAA, GDPR), eDiscovery, Vault, support prioritaire et domaine personnalisé."},
  {t:"Google Workspace",q:"Qu'est-ce que Google Drive dans le contexte professionnel ?",o:["Un disque dur externe","Un service de stockage et partage de fichiers cloud avec synchronisation, contrôle d'accès et collaboration en temps réel","Un service de sauvegarde uniquement","Un protocole de partage de fichiers réseau"],a:1,e:"Google Drive permet de stocker, accéder et partager des fichiers depuis n'importe quel appareil. En entreprise, il offre le partage granulaire (visionner/commenter/modifier), les Drive partagés pour les équipes et l'historique de versions."},
  {t:"Google Workspace",q:"Qu'est-ce que Google Meet et ses avantages pour les entreprises ?",o:["Un service de rencontres professionnelles physiques","Un service de visioconférence cloud sécurisé intégré à Google Workspace, sans limite de temps","Un service d'appels audio uniquement","Un réseau social professionnel"],a:1,e:"Google Meet est un service de visioconférence HD sécurisé intégré à Google Workspace. Il supporte les réunions jusqu'à 500 participants (selon plan), l'enregistrement dans Drive, les sous-titres et l'intégration Calendar."},
  {t:"Google Workspace",q:"Qu'est-ce que Google Chat dans Workspace ?",o:["Une application de chat non professionnelle","Un service de messagerie professionnelle en temps réel avec espaces de travail partagés, intégrations et bots","Un service d'email","Un outil de gestion de projet"],a:1,e:"Google Chat est l'outil de messagerie professionnelle de Workspace permettant la communication 1:1, les espaces d'équipe (Spaces) avec historique, le partage de fichiers, les threads et l'intégration avec d'autres services Workspace."},
  {t:"Google Workspace",q:"Qu'est-ce que Google Vault ?",o:["Un service de stockage sécurisé de mots de passe","Un service d'eDiscovery, d'archivage et de conservation des données Workspace pour les besoins légaux et réglementaires","Un service de sauvegarde simple","Un gestionnaire de fichiers sécurisé"],a:1,e:"Google Vault permet d'archiver, rechercher et exporter les données Workspace (emails, conversations, fichiers Drive) pour les audits, litiges, enquêtes et conformité réglementaire avec des politiques de rétention configurables."},
  {t:"Google Workspace",q:"Qu'est-ce que l'administration centralisée dans Google Workspace ?",o:["Une fonction réservée aux grandes entreprises","La console Admin permettant de gérer tous les utilisateurs, groupes, appareils, applications et politiques depuis une interface unifiée","Un service de gestion uniquement des licences","Un outil de facturation centralisée"],a:1,e:"La console Admin de Google Workspace permet aux administrateurs IT de gérer de façon centralisée : comptes utilisateurs, groupes, appareils (MDM), applications tierces, politiques de sécurité et rapports d'utilisation."},
  {t:"Google Workspace",q:"Qu'est-ce que Google Workspace Marketplace ?",o:["Un service e-commerce","Un catalogue d'applications tierces qui s'intègrent avec Google Workspace (CRM, gestion de projet, signature électronique)","Un service d'achat de licences Workspace","Un réseau d'entreprises partenaires Google"],a:1,e:"Google Workspace Marketplace est un catalogue d'applications tierces et d'add-ons qui s'intègrent directement dans les applications Workspace (Docs, Sheets, Gmail) pour étendre leurs fonctionnalités."},
  {t:"Google Workspace",q:"Qu'est-ce que AppSheet dans Google Workspace ?",o:["Une application mobile pour accéder à Workspace","Une plateforme no-code/low-code permettant de créer des applications mobiles et web sans programmation","Un service de gestion des applications tierces","Un outil de test d'applications"],a:1,e:"AppSheet est une plateforme no-code intégrée à Google Workspace permettant de créer des applications mobiles et web personnalisées à partir de données Sheets, Drive, BigQuery, sans écrire de code."},
  {t:"Google Workspace",q:"Qu'est-ce que Google Sites dans Workspace ?",o:["Le service de nom de domaine de Google","Un outil simple de création de sites intranet et portails d'équipe intégré à Workspace","Un service d'hébergement web avancé","Un CMS complet pour sites publics"],a:1,e:"Google Sites est un outil no-code permettant de créer facilement des sites intranet, portails de projet ou wikis d'équipe, en intégrant du contenu depuis Drive, Docs, YouTube et autres services Workspace."},
  {t:"Collaboration",q:"Qu'est-ce que la coédition en temps réel dans Google Docs/Sheets ?",o:["La sauvegarde automatique des fichiers","La capacité de plusieurs personnes à modifier simultanément le même document, chaque curseur étant affiché en couleur différente","Un service de synchronisation différée","Un outil de gestion des versions de documents"],a:1,e:"La coédition en temps réel permet à plusieurs utilisateurs de modifier simultanément le même fichier, en voyant les curseurs et modifications des autres en direct, éliminant les conflits de versions de fichiers."},
  {t:"Collaboration",q:"Qu'est-ce que les 'Shared Drives' (Drive partagé) dans Google Workspace ?",o:["Un disque dur partagé physique","Des espaces de stockage appartenant à l'équipe (pas à un individu), où les fichiers persistent même si un membre quitte","Un service de partage de liens","Un dossier partagé standard dans My Drive"],a:1,e:"Les Drive partagés sont des espaces de stockage appartenant à l'organisation/équipe (pas à un individu). Les fichiers persistent même si des membres quittent, avec des niveaux d'accès configurables (Viewer, Commenter, Contributor, Manager)."},
  {t:"Collaboration",q:"Qu'est-ce que le mode 'Suggestion' dans Google Docs ?",o:["Un outil de correction orthographique","Un mode permettant de proposer des modifications qui apparaissent comme suggestions à accepter/rejeter par le propriétaire","Un outil de recommandation de contenu","Un service de révision automatique"],a:1,e:"Le mode Suggestion dans Google Docs permet de proposer des modifications sans les appliquer directement. Les modifications apparaissent en couleur différente et le propriétaire peut les accepter ou rejeter individuellement."},
  {t:"Collaboration",q:"Qu'est-ce que Google Jamboard et son successeur ?",o:["Un outil de gestion de réunions","Un tableau blanc numérique collaboratif (remplacé par des outils tiers intégrés à Google Meet)","Un service de partage de documents","Un outil de gestion de projets"],a:1,e:"Jamboard était le tableau blanc numérique collaboratif de Google pour les réunions visuelles. Google l'a arrêté en 2024 et recommande des alternatives comme FigJam, Lucidspark ou Miro intégrées à Google Meet."},
  {t:"Collaboration",q:"Qu'est-ce que Google Workspace pour l'éducation ?",o:["Un service Workspace sans contrôles parentaux","Des éditions spéciales (Education Fundamentals gratuit, Standard, Teaching and Learning, Plus) avec outils pédagogiques et conformité COPPA","Un service identique à la version entreprise","Un service uniquement pour les universités"],a:1,e:"Google Workspace for Education propose des éditions adaptées (dont une gratuite) avec Google Classroom, Assignments, des contrôles de conformité COPPA/FERPA et des fonctionnalités pédagogiques spécifiques pour les établissements scolaires."},
  {t:"Collaboration",q:"Qu'est-ce que Google Classroom ?",o:["Une salle de classe virtuelle payante","Un outil gratuit pour les enseignants de créer des cours, distribuer des devoirs et communiquer avec les élèves","Un LMS (Learning Management System) complet","Un service de visioconférence pour les cours"],a:1,e:"Google Classroom est un outil pédagogique gratuit permettant aux enseignants de créer des cours, distribuer et corriger des devoirs, donner du feedback, gérer les notes et communiquer avec les élèves."},
  {t:"Collaboration",q:"Qu'est-ce que la fonctionnalité 'Smart Features' dans Workspace ?",o:["Des raccourcis clavier avancés","Des fonctionnalités alimentées par l'IA pour la rédaction (Smart Compose), la réponse (Smart Reply), la recherche et l'organisation","Un service premium de mise en forme automatique","Un outil de détection de plagiat"],a:1,e:"Les Smart Features utilisent l'IA Google pour proposer des compléments de texte (Smart Compose dans Gmail/Docs), des réponses suggérées (Smart Reply), la mise en forme automatique et la recherche intelligente."},
  {t:"Collaboration",q:"Qu'est-ce que Duet AI for Workspace (maintenant Gemini for Workspace) ?",o:["Un doublon de fonctionnalités existantes","L'intégration de l'IA générative Gemini dans toutes les applications Workspace pour la rédaction, résumé, analyse et génération de contenu","Un service de téléconférence avancé","Un outil de gestion des réunions IA"],a:1,e:"Gemini for Workspace intègre l'IA générative dans Gmail (rédaction, résumé), Docs (génération de contenu), Sheets (analyse de données), Slides (création), Meet (notes automatiques) et Chat."},
  {t:"Collaboration",q:"Qu'est-ce que Google Keep dans Workspace ?",o:["Un service de stockage de mots de passe","Un outil de prise de notes rapides, listes et rappels, synchronisé et intégré à Docs/Slides","Un service de sauvegarde","Un outil de gestion de tâches avancé"],a:1,e:"Google Keep est un outil de prise de notes rapides (texte, audio, images, listes) avec organisation par couleurs et étiquettes, rappels géolocalisés et intégration directe dans Google Docs et Slides."},
  {t:"Collaboration",q:"Qu'est-ce que Google Tasks dans Workspace ?",o:["Un gestionnaire de projet complet","Un outil simple de gestion de tâches personnelles intégré à Gmail et Calendar","Un service de tickets de support","Un outil de gestion des ressources humaines"],a:1,e:"Google Tasks est un gestionnaire de tâches simple intégré à Gmail et Calendar permettant de créer des listes de tâches, sous-tâches, dates d'échéance et de voir les tâches dans le calendrier."},
  {t:"Sécurité Workspace",q:"Qu'est-ce que le DLP dans Google Workspace ?",o:["Data Loss Prevention — des règles automatiques détectant et protégeant les données sensibles dans Gmail, Drive et Chat","Un service de détection de logiciels espions","Un protocole de communication sécurisé","Un outil de gestion des licences"],a:0,e:"Le DLP Workspace applique des règles automatiques pour détecter les données sensibles (numéros de carte, SSN) dans Gmail, Drive et Chat, et peut bloquer le partage, avertir les utilisateurs ou chiffrer automatiquement."},
  {t:"Sécurité Workspace",q:"Qu'est-ce que le 'Context-Aware Access' dans Workspace ?",o:["Un accès basé uniquement sur la localisation géographique","Un contrôle d'accès granulaire basé sur l'identité de l'utilisateur, l'état de l'appareil, l'IP et d'autres contextes","Un accès uniquement depuis les appareils de l'entreprise","Un service d'accès conditionnel uniquement pour mobile"],a:1,e:"Context-Aware Access dans Workspace (basé sur BeyondCorp) permet de configurer des niveaux d'accès aux applications Workspace en fonction du contexte : identité, état de l'appareil (MDM), adresse IP, emplacement."},
  {t:"Sécurité Workspace",q:"Qu'est-ce que Google Endpoint Management dans Workspace ?",o:["La gestion des ordinateurs de bureau uniquement","Un service MDM (Mobile Device Management) pour gérer et sécuriser les appareils accédant à Workspace","Un service de gestion des API endpoints","Un outil de gestion des points de terminaison réseau"],a:1,e:"Endpoint Management dans Workspace permet de gérer les appareils (mobiles, ChromeOS, Windows) accédant aux données Workspace : application de politiques de sécurité, effacement à distance et inventaire des appareils."},
  {t:"Sécurité Workspace",q:"Qu'est-ce que la vérification en 2 étapes (2SV) dans Workspace ?",o:["Un processus de vérification en deux phases pour les documents","Une sécurité additionnelle exigeant un second facteur (SMS, app Authenticator, clé de sécurité) en plus du mot de passe","Un service de double sauvegarde","Un protocole de chiffrement en deux couches"],a:1,e:"La vérification en 2 étapes protège les comptes Workspace en exigeant un second facteur d'authentification (code SMS, Google Authenticator, clé de sécurité physique FIDO2) en plus du mot de passe."},
  {t:"Sécurité Workspace",q:"Qu'est-ce que la protection contre le phishing dans Gmail ?",o:["Un filtre de spam uniquement","Des protections avancées incluant la détection IA des emails malveillants, sandbox des pièces jointes et vérification DMARC","Un service de signature électronique","Un protocole de chiffrement des emails"],a:1,e:"Gmail Enterprise inclut une protection avancée : ML pour détecter les emails malveillants, sandbox (exécution sécurisée des pièces jointes), vérification DMARC/DKIM/SPF et alertes pour les usurpations d'identité."},
  {t:"Sécurité Workspace",q:"Qu'est-ce que le chiffrement côté client (CSE) dans Workspace ?",o:["Le chiffrement standard de Workspace","Un chiffrement géré par le client avec ses propres clés, rendant les données illisibles pour Google","Un chiffrement SSL/TLS pour les connexions","Un service de chiffrement des fichiers locaux"],a:1,e:"Client-Side Encryption (CSE) permet de chiffrer les données Workspace (Drive, Docs, Gmail, Meet) avec des clés contrôlées par le client (via un service de clés externe), rendant les données illisibles pour Google."},
  {t:"Workspace Admin",q:"Que permet la console Admin de Google Workspace ?",o:["Uniquement la gestion des licences","La gestion centralisée des utilisateurs, groupes, appareils, politiques de sécurité, applications et rapports","L'administration uniquement des emails","La gestion uniquement des données dans Drive"],a:1,e:"La console Admin est le tableau de bord centralisé permettant aux administrateurs de gérer tous les aspects de Workspace : utilisateurs/groupes, appareils, applications tierces, politiques de sécurité et conformité."},
  {t:"Workspace Admin",q:"Qu'est-ce que les 'Organizational Units' (OU) dans Workspace ?",o:["Des unités de mesure organisationnelle","Des structures hiérarchiques permettant d'appliquer des politiques différentes à des sous-groupes d'utilisateurs","Des groupes de sécurité réseau","Des unités de facturation"],a:1,e:"Les Organizational Units permettent d'organiser les utilisateurs en hiérarchies dans la console Admin et d'appliquer des politiques différentes à des départements ou groupes spécifiques."},
  {t:"Workspace Admin",q:"Qu'est-ce que le 'Directory' dans Google Workspace ?",o:["Un service de gestion de fichiers","L'annuaire centralisé de l'organisation listant les utilisateurs, groupes et ressources partagées (salles, équipements)","Un service de messagerie","Un outil de gestion des contacts personnels"],a:1,e:"Le Directory de Workspace est l'annuaire de l'organisation contenant les profils des utilisateurs (nom, email, téléphone, photo), les groupes et les ressources (salles de réunion, équipements) visibles par tous."},
  {t:"Workspace Admin",q:"Qu'est-ce que Google Workspace Migration Tool ?",o:["Un outil de migration vers un autre fournisseur","Des outils aidant à migrer les données (emails, calendriers, contacts) depuis Exchange, Office 365 ou d'autres systèmes vers Workspace","Un outil de migration de données BigQuery","Un service de migration des applications vers le cloud"],a:1,e:"Google propose des outils de migration (GAMME, Data Migration Service) pour déplacer les emails, calendriers et contacts depuis Microsoft Exchange, Office 365, Lotus Notes ou d'autres systèmes vers Google Workspace."},
  {t:"Workspace Admin",q:"Qu'est-ce que les rapports d'utilisation dans la console Admin Workspace ?",o:["Des rapports de facturation uniquement","Des tableaux de bord montrant l'adoption des services, l'activité des utilisateurs et les métriques de sécurité","Des rapports de performance réseau","Des rapports de maintenance des serveurs"],a:1,e:"Les rapports Admin Workspace fournissent des insights sur l'adoption des services (qui utilise quoi), l'activité des utilisateurs, les alertes de sécurité et les métriques de conformité pour guider les décisions IT."},
  {t:"Workspace Admin",q:"Qu'est-ce que Google Workspace Assured Controls ?",o:["Un service de contrôle qualité","Des contrôles additionnels de conformité pour les secteurs réglementés (gouvernement, santé), limitant l'accès des employés Google aux données","Un service de gestion des risques","Un outil d'audit des configurations"],a:1,e:"Assured Controls for Workspace offre des contrôles additionnels pour les organisations très réglementées : restrictions sur les accès du personnel Google, résidence des données et conformité avec des frameworks gouvernementaux."},
  {t:"Workspace Editions",q:"Qu'est-ce que Workspace Business Starter ?",o:["L'édition la plus complète de Workspace","La version d'entrée de gamme de Workspace avec 30GB de stockage pooled, 100 participants Meet et les fonctionnalités de base","Une version gratuite de Workspace","Un service uniquement pour les équipes de moins de 5 personnes"],a:1,e:"Business Starter est le plan d'entrée de Google Workspace, incluant 30GB de stockage groupé par utilisateur, réunions Meet jusqu'à 100 participants, email professionnel et outils de collaboration standard."},
  {t:"Workspace Editions",q:"Quelle édition Workspace inclut eDiscovery et Vault ?",o:["Business Starter","Business Standard","Business Plus et Enterprise","Toutes les éditions"],a:2,e:"Google Vault (eDiscovery, archivage et conservation) est inclus dans Business Plus et toutes les éditions Enterprise. Il permet de rechercher, conserver et exporter les données pour les besoins légaux et réglementaires."},
  {t:"Workspace Editions",q:"Qu'est-ce que Workspace Enterprise Plus ?",o:["L'édition standard pour grandes entreprises","L'édition la plus complète avec stockage illimité, toutes les fonctionnalités de sécurité avancées, SLA renforcé et support premium","Une version Workspace uniquement pour les établissements scolaires","Une édition uniquement disponible sur devis"],a:1,e:"Enterprise Plus est l'édition la plus complète de Workspace, incluant toutes les fonctionnalités (DLP avancé, CSE, Vault, rapports avancés), stockage illimité, SLA 99.9%, et support avec TAM (Technical Account Manager)."},
  {t:"Workspace Editions",q:"Qu'est-ce que Google Workspace Essentials ?",o:["La version de base avec email","Une édition sans email Gmail, incluant Meet, Drive, Docs, Chat — pour les organisations utilisant un autre système d'email","Une édition gratuite pour les associations","Un service de collaboration sans stockage"],a:1,e:"Workspace Essentials est conçu pour les organisations qui conservent leur système email existant (Outlook) et veulent seulement les outils de collaboration Google (Meet, Drive, Docs, Sheets, Slides, Chat)."},
  {t:"Workspace Intégration",q:"Comment Google Workspace s'intègre-t-il avec GCP ?",o:["Aucune intégration possible","Via des connecteurs natifs : BigQuery pour les données Sheets, Vertex AI pour les fonctionnalités IA, IAM pour les contrôles d'accès","Uniquement via des APIs tierces","L'intégration nécessite des outils tiers"],a:1,e:"Google Workspace s'intègre nativement avec GCP : BigQuery via Connected Sheets, Cloud Identity pour IAM partagé, Vertex AI pour les Smart Features, Cloud Logging pour les audits et PubSub pour les événements."},
  {t:"Workspace Intégration",q:"Qu'est-ce que l'API Google Workspace ?",o:["Une API uniquement pour les développeurs Google","Un ensemble d'APIs permettant aux applications tierces d'accéder et interagir programmatiquement avec les données et fonctionnalités Workspace","Un protocole de communication entre applications Workspace","Un service d'extension des fonctionnalités Workspace"],a:1,e:"Les APIs Google Workspace (Gmail API, Drive API, Calendar API, etc.) permettent aux développeurs de créer des applications intégrant les fonctionnalités Workspace, d'automatiser des workflows et d'accéder aux données professionnelles."},
  {t:"Workspace Intégration",q:"Qu'est-ce que Google Workspace Add-ons ?",o:["Des modules payants pour Workspace","Des extensions développées en Apps Script ou via les APIs qui s'intègrent dans Gmail, Docs, Sheets et Calendar","Des applications mobiles pour Workspace","Des composants matériels pour Google Meet"],a:1,e:"Les Workspace Add-ons sont des extensions créées avec Google Apps Script ou via les APIs qui ajoutent des fonctionnalités directement dans l'interface des applications Workspace (Gmail, Docs, Sheets, Calendar)."},
  {t:"Workspace Intégration",q:"Qu'est-ce que Google Apps Script ?",o:["Un langage de programmation Google propriétaire","Un environnement de scripting JavaScript basé sur le cloud pour automatiser et étendre Google Workspace","Un outil de débogage pour applications Workspace","Un service de compilation de code JavaScript"],a:1,e:"Apps Script est un environnement de développement basé sur JavaScript permettant d'automatiser les tâches Google Workspace, créer des add-ons, construire des applications web légères et interagir avec les APIs Google."},
  {t:"Workspace Intégration",q:"Comment Google Workspace gère-t-il la conformité RGPD ?",o:["Google Workspace n'est pas conforme au RGPD","Via des DPA (Data Processing Agreements), des contrôles de résidence des données, des rapports d'activité et des outils d'anonymisation","La conformité RGPD est la responsabilité uniquement du client","Via un système de certification automatique"],a:1,e:"Google Workspace soutient la conformité RGPD via des DPA avec les clients, des contrôles de localisation des données, Access Transparency, Vault pour la conservation des données et des rapports d'audit détaillés."},
  {t:"Workspace Intégration",q:"Qu'est-ce que la migration vers Google Workspace via 'lift and shift' ?",o:["La migration physique des serveurs","La migration directe des emails, calendriers et contacts depuis l'ancien système vers Workspace sans refonte","La recréation complète de l'environnement","Un service de migration partielle"],a:1,e:"La migration 'lift and shift' vers Workspace consiste à migrer directement les données existantes (emails, calendriers, contacts) depuis Exchange/Office 365 vers Workspace sans restructuration, en utilisant les outils de migration Google."},
  {t:"Workspace Intégration",q:"Qu'est-ce que 'Work Insights' dans Google Workspace ?",o:["Un service d'analyse des performances des employés","Un outil d'analyse de l'adoption et de l'utilisation des produits Workspace pour les administrateurs","Un service de surveillance individuelle des employés","Un outil de feedback employé"],a:1,e:"Work Insights (pour Enterprise) fournit aux administrateurs des données agrégées et anonymisées sur l'adoption des produits Workspace, les patterns de collaboration et le temps économisé, pour orienter les investissements IT."},
  {t:"Workspace Intégration",q:"Qu'est-ce que la fonctionnalité 'Spaces' dans Google Chat ?",o:["Des espaces de stockage supplémentaires","Des canaux de discussion persistants pour les équipes avec historique, partage de fichiers, threads et intégration de bots","Des espaces de réunion virtuels","Des zones de travail dans Google Docs"],a:1,e:"Les Spaces dans Google Chat sont des canaux persistants permettant à des équipes de collaborer de façon organisée avec historique des messages, partage de fichiers, bots/intégrations, threads et accès depuis Drive."},
  {t:"Workspace Intégration",q:"Qu'est-ce que 'Google Meet Hardware' ?",o:["Des caméras uniquement pour Google Meet","Des kits matériels certifiés (caméras, micros, écrans) pour équiper les salles de réunion avec une expérience Meet optimale","Des ordinateurs spéciaux pour Google Meet","Des serveurs dédiés pour les réunions d'équipe"],a:1,e:"Google Meet Hardware est une gamme d'équipements certifiés (Chromebox for Meetings, Series One par Lenovo et ASUS) conçus pour fournir une expérience de visioconférence Meet optimale dans les salles de réunion physiques."}
];


window.QDATA[7] = [
  {t:"Transformation digitale",q:"Qu'est-ce que la transformation digitale selon Google Cloud ?",o:["La migration des données vers le cloud uniquement","Le processus d'utilisation des technologies digitales pour transformer fondamentalement les opérations, la culture et la livraison de valeur d'une organisation","L'achat de nouveaux logiciels","La numérisation des documents papier"],a:1,e:"La transformation digitale est le processus de réinvention fondamentale d'une organisation grâce aux technologies numériques, touchant les opérations, l'expérience client, les modèles économiques et la culture d'entreprise."},
  {t:"Transformation digitale",q:"Quels sont les trois niveaux de maturité cloud selon Google Cloud ?",o:["Débutant, intermédiaire, avancé","Tactique (infrastructure as a service), stratégique (automatisation), transformationnel (innovation data/IA)","Petit, moyen, grand","Public, privé, hybride"],a:1,e:"Google Cloud décrit trois niveaux : le niveau tactique (migrer l'infrastructure, réduire les coûts), le niveau stratégique (automatiser, améliorer l'efficacité), et le niveau transformationnel (innover avec la data et l'IA)."},
  {t:"Transformation digitale",q:"Qu'est-ce que le 'Cloud Journey' (parcours cloud) d'une organisation ?",o:["Un voyage d'affaires pour visiter des data centers Google","Le chemin progressif d'une organisation dans l'adoption du cloud, depuis les premiers projets pilotes jusqu'à la transformation complète","Un programme de formation Google Cloud","Un contrat de migration vers le cloud"],a:1,e:"Le Cloud Journey décrit l'évolution progressive d'une organisation : évaluation et planification, migration des premières charges de travail, optimisation, puis innovation et transformation digitale complète."},
  {t:"Transformation digitale",q:"Qu'est-ce que le concept 'digital native' dans le contexte cloud ?",o:["Un natif numérique — une personne née après l'an 2000","Une entreprise conçue dès le départ avec une architecture cloud-native, sans héritage IT traditionnel","Un type de certification Google Cloud","Un service pour les startups uniquement"],a:1,e:"Les 'digital natives' sont des organisations nées dans le cloud (startup tech, fintechs, etc.) qui n'ont pas de dette technique héritée et peuvent tirer pleinement parti des avantages du cloud dès leur création."},
  {t:"Transformation digitale",q:"Qu'est-ce que le ROI (Return on Investment) du cloud selon Google Cloud ?",o:["Uniquement les économies sur les serveurs","Une combinaison : économies d'infrastructure, réduction du time-to-market, innovation accélérée, nouvelles sources de revenus et amélioration de l'expérience client","La réduction uniquement des coûts IT","Le bénéfice sur les achats de licences logicielles"],a:1,e:"Le ROI cloud est multidimensionnel : économies sur l'infrastructure (TCO), gains d'efficacité opérationnelle, time-to-market réduit, capacité d'innovation accélérée, nouvelles opportunités de revenus et amélioration de l'expérience client."},
  {t:"Transformation digitale",q:"Qu'est-ce que la 'dette technique' et comment le cloud aide-t-il à la réduire ?",o:["Les impayés des factures IT","L'accumulation de systèmes obsolètes et de code difficile à maintenir; le cloud permet une modernisation progressive","Une taxe sur les achats technologiques","Les coûts de formation des équipes IT"],a:1,e:"La dette technique est l'accumulation de systèmes anciens et de code difficile à maintenir. Le cloud aide à la réduire via la modernisation progressive des applications, l'adoption de services managés et l'automatisation."},
  {t:"Transformation digitale",q:"Qu'est-ce que la stratégie 'cloud-first' ?",o:["Utiliser uniquement le cloud public","Évaluer le cloud comme option prioritaire pour tout nouveau projet IT avant d'envisager des solutions on-premises","Migrer toutes les applications existantes immédiatement","Utiliser uniquement les services Google Cloud"],a:1,e:"Une stratégie cloud-first signifie que, pour tout nouveau besoin IT, le cloud est évalué en priorité comme solution. Cela ne signifie pas migrer tout immédiatement, mais considérer le cloud avant l'on-premises."},
  {t:"Transformation digitale",q:"Qu'est-ce que l'innovation ouverte avec Google Cloud ?",o:["Le partage gratuit de la technologie Google","L'accès aux écosystèmes open source, partenaires technologiques et marketplaces pour accélérer l'innovation","Un programme de collaboration avec des startups uniquement","Un service d'aide à la création de brevets"],a:1,e:"L'innovation ouverte avec GCP inclut l'intégration de l'écosystème open source (Kubernetes, TensorFlow, Apache Beam), les solutions partenaires dans le Marketplace et les intégrations avec des services tiers."},
  {t:"Transformation digitale",q:"Qu'est-ce que le 'Time to Market' et comment GCP l'améliore-t-il ?",o:["Le temps de livraison des produits physiques","La rapidité pour lancer de nouveaux produits/fonctionnalités; GCP accélère cela via des services managés, DevOps et automatisation","La vitesse de connexion à internet","La durée des contrats Google Cloud"],a:1,e:"Le Time to Market est le temps nécessaire pour passer d'une idée à un produit en production. GCP l'accélère via des services PaaS/SaaS managés, les outils DevOps, CI/CD, le déploiement automatisé et les environnements de développement rapide."},
  {t:"Transformation digitale",q:"Qu'est-ce que la résilience organisationnelle et le rôle du cloud ?",o:["La résistance physique des data centers","La capacité d'une organisation à s'adapter et continuer à fonctionner face aux perturbations; le cloud apporte scalabilité et disponibilité pour y contribuer","Un programme d'assurance pour les entreprises IT","Un système de gestion des ressources humaines"],a:1,e:"La résilience organisationnelle est la capacité à faire face aux perturbations (pandémies, crises, cyberattaques). Le cloud contribue par sa haute disponibilité, son élasticité, la reprise après sinistre et le télétravail."},
  {t:"Cas d'usage GCP",q:"Comment une entreprise de retail peut-elle utiliser GCP pour améliorer l'expérience client ?",o:["En migrant uniquement son site web","Via BigQuery pour analyser les comportements d'achat, Vertex AI pour les recommandations personnalisées, et Spanner pour l'inventaire global en temps réel","En utilisant uniquement Cloud Storage","En remplaçant ses caisses enregistreuses"],a:1,e:"Un retailer peut utiliser : BigQuery pour analyser les données clients/transactions, Vertex AI pour les recommandations personnalisées, Cloud Spanner pour l'inventaire global temps réel, et Looker pour les dashboards business."},
  {t:"Cas d'usage GCP",q:"Comment une banque peut-elle utiliser GCP pour la détection de fraude ?",o:["En stockant les transactions dans Cloud Storage","En utilisant Vertex AI pour construire des modèles ML de détection d'anomalies, Pub/Sub pour le streaming de transactions et BigQuery pour l'analyse historique","En migrant uniquement son site web","En utilisant Gmail pour les alertes"],a:1,e:"Une banque utilise GCP pour la fraude via : Pub/Sub pour ingérer les transactions en temps réel, Dataflow pour le traitement streaming, Vertex AI pour les modèles de détection d'anomalies, et BigQuery pour l'analyse forensique."},
  {t:"Cas d'usage GCP",q:"Comment une entreprise de santé peut-elle utiliser GCP en respectant HIPAA ?",o:["Elle ne peut pas utiliser GCP pour des données de santé","Via Cloud Healthcare API pour les données HL7/FHIR, BigQuery pour l'analyse médicale, Vertex AI pour la prédiction clinique — GCP est conforme HIPAA avec BAA","En utilisant uniquement des services on-premises","En anonymisant toutes les données avant usage"],a:1,e:"GCP supporte HIPAA : Cloud Healthcare API gère les données HL7/FHIR/DICOM, BigQuery permet l'analyse de populations, Vertex AI aide au diagnostic prédictif, et Google signe des BAA (Business Associate Agreements)."},
  {t:"Cas d'usage GCP",q:"Comment une startup peut-elle tirer parti de GCP pour évoluer rapidement ?",o:["En achetant des serveurs avec le programme startup de Google","Via Firebase pour l'application mobile, Cloud Run pour le backend serverless, Firestore pour les données, et les crédits Google Cloud for Startups","En utilisant uniquement des services gratuits","En développant uniquement des applications Google"],a:1,e:"Une startup utilise GCP via : Firebase pour le développement rapide d'apps mobiles, Cloud Run pour des microservices serverless scalables, Firestore pour les données NoSQL, BigQuery pour l'analytics — et bénéficie de crédits startup."},
  {t:"Cas d'usage GCP",q:"Comment une entreprise manufacturière peut-elle utiliser GCP pour l'IoT ?",o:["En remplaçant ses machines par des versions Google","Via Cloud IoT Core pour connecter les capteurs, Pub/Sub pour ingérer les données temps réel, Dataflow pour le traitement, BigQuery pour l'analyse prédictive de maintenance","En utilisant uniquement des capteurs Google","En migrant uniquement son ERP"],a:1,e:"Un manufacturier utilise GCP pour l'IoT industriel : Cloud IoT Core pour gérer les appareils connectés, Pub/Sub pour l'ingestion de données capteurs, Dataflow pour le traitement, Vertex AI pour la maintenance prédictive."},
  {t:"Exam Final",q:"Un CTO souhaite réduire le TCO de 30% tout en maintenant les performances. Quelle approche GCP recommandez-vous ?",o:["Migrer tout en IaaS (Compute Engine) uniquement","Adopter une stratégie mixte : migrer les charges existantes vers des services managés (PaaS), utiliser les Committed Use Discounts, et optimiser avec les recommandations de coûts","Réduire le nombre de régions utilisées","Désactiver les sauvegardes pour économiser"],a:1,e:"Pour réduire le TCO : migrer vers PaaS (Cloud Run, App Engine, Cloud SQL) pour réduire l'administration, utiliser CUD/SUDs pour les charges stables, activer les recommandations de coûts GCP, et rightsizer les ressources sous-utilisées."},
  {t:"Exam Final",q:"Une entreprise doit garantir que ses données clients européens restent en Europe. Quelle fonctionnalité GCP utiliser ?",o:["Il est impossible de garantir la localisation sur le cloud","Les 'Organizational Policies' avec les contraintes de localisation des ressources, les régions européennes (europe-west) et les contrôles de résidence des données","Uniquement en utilisant un cloud privé","En chiffrant toutes les données avec CMEK"],a:1,e:"GCP permet la résidence des données via : sélection des régions européennes (europe-west1, 2, 3, 4...), Organizational Policies pour restreindre la création de ressources hors UE, et les accords de traitement des données conformes au RGPD."},
  {t:"Exam Final",q:"Un directeur marketing veut analyser en temps réel les interactions sur le site web pour personnaliser l'expérience. Quelle architecture GCP convient ?",o:["Stocker toutes les données puis analyser mensuellement","Pub/Sub pour collecter les événements → Dataflow pour le traitement streaming → BigQuery pour l'analyse → Vertex AI pour les recommandations → Firestore pour servir les recommandations","Utiliser uniquement Google Analytics","Analyser les logs manuellement"],a:1,e:"Pour la personnalisation temps réel : Pub/Sub ingère les clics/events, Dataflow traite le stream, BigQuery analyse les patterns, Vertex AI génère des recommandations ML, et Firestore sert les recommandations à l'application avec une faible latence."},
  {t:"Exam Final",q:"Une organisation veut migrer 500 VMs d'un datacenter on-premises vers GCP. Quelle est la première étape recommandée ?",o:["Migrer immédiatement toutes les VMs","Évaluer le parc avec Migrate to Virtual Machines (anciennement Velostrata), prioriser les charges de travail, créer un plan de migration par phases","Reconstruire toutes les applications en cloud-native","Acheter un contrat Enterprise GCP immédiatement"],a:1,e:"La première étape est l'évaluation (discovery) : utiliser Migrate to Virtual Machines pour inventorier les VMs, évaluer les dépendances, calculer le TCO et prioriser les migrations par vague (lift-and-shift d'abord, puis modernisation)."},
  {t:"Exam Final",q:"Un CISO s'inquiète des accès des employés de Google à ses données. Quelle fonctionnalité GCP adresse ce besoin ?",o:["Il est impossible d'empêcher les accès Google","Access Transparency (journalisation des accès du personnel Google) et Assured Workloads pour les restrictions contractuelles d'accès","En chiffrant uniquement avec AES-256","En n'utilisant que des services open source"],a:1,e:"Access Transparency enregistre les accès du personnel Google aux données client avec des justifications. Assured Workloads ajoute des contrôles contractuels. CMEK et EKM permettent au client de contrôler ses clés de chiffrement."},
  {t:"Exam Final",q:"Une application web doit gérer des pics de trafic imprévisibles (x10 en quelques minutes). Quelle architecture GCP recommander ?",o:["Surprovisioner des Compute Engine pour anticiper les pics","Cloud Run (autoscaling serverless de 0 à N instances) avec un Load Balancer Global et Cloud CDN pour les assets statiques","Utiliser uniquement des VMs préemptibles","Configurer manuellement des scripts de scaling"],a:1,e:"Pour des pics imprévisibles : Cloud Run scale automatiquement de 0 à N instances en secondes, le Load Balancer Global distribue le trafic mondialement, Cloud CDN met en cache les assets, et Firestore/Spanner gèrent la concurrence des données."},
  {t:"Exam Final",q:"Quelle est la différence entre 'migration lift-and-shift' et 'cloud-native re-architecture' ?",o:["Il n'y a pas de différence","Lift-and-shift = migrer l'application existante sans changement vers IaaS (plus rapide, moins de bénéfices cloud); re-architecture = réécrire pour tirer pleinement parti du cloud (plus long, plus de bénéfices)","Lift-and-shift est réservé aux grandes entreprises","Re-architecture est uniquement pour les startups"],a:1,e:"Lift-and-shift (rehosting) est rapide mais ne tire pas pleinement parti du cloud. La re-architecture (refactoring/rebuilding) est plus longue mais offre tous les avantages : scalabilité, résistance aux pannes, réduction TCO, serverless."},
  {t:"Exam Final",q:"Un retailer veut créer une application de recommandation de produits. Quel service GCP utiliser pour le modèle ML ?",o:["BigQuery uniquement","Vertex AI — qui offre AutoML pour créer des modèles sans expertise ML profonde, ou des pipelines ML personnalisés pour les data scientists","Cloud Functions pour une logique simple","Dataflow pour le traitement des recommandations"],a:1,e:"Vertex AI est le service ML unifié de GCP : AutoML Recommendations permet de créer un système de recommandation sans expertise ML profonde, en partant des données historiques d'achats/clics du retailer."},
  {t:"Exam Final",q:"Comment GCP aide-t-il les entreprises à respecter le RGPD ?",o:["GCP exempte automatiquement les clients du RGPD","Via les contrôles de résidence des données, les DPA contractuels, DLP API pour détecter les données personnelles, Access Transparency, et les outils d'anonymisation/suppression","Le RGPD ne s'applique pas aux données cloud","En chiffrant uniquement les données en transit"],a:1,e:"GCP supporte le RGPD via : résidence des données en UE, Data Processing Addendum, Cloud DLP pour détecter/anonymiser les PII, Access Transparency pour l'audit, droit à l'effacement via les APIs, et les certifications de conformité."},
  {t:"Exam Final",q:"Quelle est la proposition de valeur principale de Anthos pour les grandes entreprises ?",o:["Un service de migration uniquement","Une plateforme de gestion d'applications multi-cloud et hybride permettant d'utiliser les mêmes outils (Kubernetes) sur GCP, d'autres clouds et on-premises","Un service de virtualisation uniquement","Un outil de monitoring uniquement"],a:1,e:"Anthos permet aux entreprises de gérer des applications Kubernetes de façon cohérente sur GCP, AWS, Azure et des infrastructures on-premises, avec des politiques de sécurité et des outils opérationnels unifiés."},
  {t:"Exam Final",q:"Un directeur financier demande comment prévoir les coûts GCP pour budgétisation. Quels outils utiliser ?",o:["Demander des devis à Google support","Google Cloud Pricing Calculator pour l'estimation, Budget Alerts pour les alertes, Cost Explorer pour l'analyse, et les CUD pour les engagements pluriannuels","Estimer basé sur les prix AWS","Utiliser uniquement la facturation mensuelle"],a:1,e:"Pour budgétiser GCP : le Pricing Calculator estime les coûts avant déploiement, les Budget Alerts préviennent les dépassements, les rapports de coûts/billing analysent les dépenses, les CUD fixent les coûts pour 1-3 ans."},
  {t:"Exam Final",q:"Qu'est-ce qu'un 'Landing Zone' sur GCP ?",o:["Une zone géographique de data centers","Un environnement GCP de base correctement configuré (organisation, facturation, réseau, sécurité, accès) servant de fondation pour déployer des charges de travail","Une zone d'atterrissage pour les drones","Un espace de stockage temporaire"],a:1,e:"Un Landing Zone GCP est l'environnement de base préconfigué : hiérarchie Organisation/Dossiers/Projets, VPC partagé, politiques IAM, contrôles de sécurité, logging centralisé — sur lequel les équipes peuvent déployer leurs applications."},
  {t:"Exam Final",q:"Comment GCP supporte-t-il la stratégie 'FinOps' ?",o:["GCP ne soutient pas le FinOps","Via les outils de visibilité des coûts (Cost Breakdown), l'attribution par labels/équipes, les recommandations d'optimisation (Rightsizer), les budgets/alertes et les CUD/SUDs","FinOps n'est applicable qu'aux entreprises>1000 employés","Via uniquement les réductions tarifaires annuelles"],a:1,e:"GCP soutient le FinOps via : étiquettes (labels) pour attribuer les coûts par équipe/projet, Cost Breakdown par service/label, recommandations d'optimisation automatiques, Budget Alerts, et les modèles d'engagement (CUD) pour prévisibilité."},
  {t:"Exam Final",q:"Une organisation a des données très sensibles sur un cluster Kubernetes on-premises. Comment peut-elle utiliser les services GCP IA sans déplacer les données ?",o:["Il est impossible d'utiliser GCP IA sans déplacer les données","Via Anthos pour le cluster hybride et l'inférence Vertex AI sur GKE on-premises, ou en utilisant des modèles exportés s'exécutant localement","En copiant les données chiffrées vers GCP","En utilisant uniquement les APIs IA publiques"],a:1,e:"Pour l'IA avec données sensibles on-premises : Anthos permet de gérer le cluster on-premises avec GCP, Vertex AI peut déployer des modèles en inférence locale sur GKE Anthos, ou les modèles peuvent être exportés et exécutés on-premises."},
  {t:"Exam Final",q:"Qu'est-ce que le concept 'Zero Trust' dans la sécurité cloud et comment GCP l'implémente-t-il ?",o:["Un système où personne n'a accès par défaut, jamais","Un modèle où la confiance n'est jamais accordée implicitement, même sur le réseau interne; GCP l'implémente via BeyondCorp Enterprise, IAM granulaire et vérification continue","Un réseau sans pare-feu","Un service de sécurité GCP pour les startups"],a:1,e:"Zero Trust signifie ne jamais faire confiance, toujours vérifier. GCP l'implémente via BeyondCorp Enterprise (accès basé sur l'identité et le contexte), IAM granulaire, VPC Service Controls et les politiques d'accès Context-Aware."},
  {t:"Exam Final",q:"Comment évaluer si une organisation est prête pour une migration GCP (Cloud Readiness Assessment) ?",o:["Uniquement en testant la vitesse internet","En évaluant : maturité technique des équipes, état de l'inventaire applicatif, dépendances, objectifs business, gouvernance IT et modèle opérationnel cible","En achetant simplement des licences GCP","En migrant d'abord un projet pilote sans évaluation préalable"],a:1,e:"Un Cloud Readiness Assessment évalue : inventaire et dépendances des applications, compétences des équipes, maturité des pratiques DevOps, objectifs business, conformité/sécurité requise et modèle opérationnel cible (CCoE)."},
  {t:"Récap Global",q:"Quel service GCP choisir pour une base de données relationnelle entièrement managée, scalable et multi-régions ?",o:["Cloud SQL","Cloud Spanner — base de données relationnelle distribuée, cohérente, multi-régions, scalable horizontalement — contrairement à Cloud SQL qui est régional","Firestore","BigQuery"],a:1,e:"Cloud Spanner est la base de données relationnelle de GCP pour les besoins exigeant une forte cohérence à l'échelle mondiale, une disponibilité maximale et une scalabilité horizontale. Cloud SQL est pour les bases relationnelles régionales managées."},
  {t:"Récap Global",q:"Quelle est la différence clé entre Pub/Sub et Cloud Tasks ?",o:["Aucune différence","Pub/Sub est pour la messagerie async à haute échelle (fan-out, streaming); Cloud Tasks gère des files d'attente de tâches avec contrôle de déduplication, délai et garantie d'exécution exactement une fois","Pub/Sub est plus récent","Cloud Tasks est moins cher"],a:1,e:"Pub/Sub est orienté streaming/événements avec distribution à plusieurs abonnés (fan-out). Cloud Tasks est pour les files de tâches d'arrière-plan avec contrôle précis (déduplication, délai de livraison, nombre de tentatives)."},
  {t:"Récap Global",q:"Dans quel cas utiliser Cloud Armor plutôt qu'un simple pare-feu VPC ?",o:["Jamais, un pare-feu VPC suffit toujours","Cloud Armor pour la protection des applications web exposées (WAF, protection DDoS L7, règles géographiques, protection contre OWASP Top 10); pare-feu VPC pour le filtrage réseau L3/L4 interne","Cloud Armor uniquement pour les grandes entreprises","Le pare-feu VPC pour tout trafic HTTPS"],a:1,e:"Cloud Armor est un WAF/anti-DDoS de couche 7 protégeant les applications web accessibles depuis internet contre les attaques DDoS volumétriques et applicatives, les injections SQL, XSS, etc. Le pare-feu VPC filtre le trafic réseau L3/L4."},
  {t:"Récap Global",q:"Quel est le modèle de responsabilité partagée pour GCP en mode PaaS ?",o:["Google est responsable de tout","Le client est responsable des données et du code applicatif; Google gère l'infrastructure, OS, middleware, runtime et la plateforme","Le client est responsable de tout","La responsabilité est identique au modèle IaaS"],a:1,e:"En PaaS : Google gère infrastructure physique, réseau, OS, runtime et plateforme. Le client est responsable de ses données, du code applicatif, des configurations de l'application et de la gestion des accès IAM."},
  {t:"Récap Global",q:"Comment GCP garantit-il la haute disponibilité pour les applications critiques ?",o:["Via des sauvegardes uniquement","Via le déploiement multi-zones (zones différentes d'une région) ou multi-régions, les Load Balancers globaux, les SLAs contractuels et les health checks automatiques","En dupliquant les données dans un seul datacenter","Via des contrats d'assurance uniquement"],a:1,e:"La haute disponibilité GCP s'obtient via : déploiement multi-zones (minimum pour HA), multi-régions pour la résilience aux pannes régionales, Load Balancer Global, failover automatique et SLAs jusqu'à 99.99% pour les services managés."},
  {t:"Récap Global",q:"Quel est l'avantage principal de Cloud Run par rapport à une VM Compute Engine pour une API REST ?",o:["Compute Engine est toujours meilleur","Cloud Run est serverless (pas de gestion d'infrastructure, scale to zero, facturation à la requête, déploiement en secondes depuis une image Docker) — idéal pour les APIs avec trafic variable","Cloud Run est plus cher","Compute Engine offre plus de flexibilité de langages"],a:1,e:"Cloud Run élimine la gestion des VMs (OS, patches, capacity planning), scale automatiquement y compris à zéro instance (coût nul sans trafic), déploie depuis un conteneur en secondes et facture uniquement les CPU/mémoire utilisés par les requêtes."},
  {t:"Récap Global",q:"Qu'est-ce que le 'Data Mesh' et comment GCP le soutient-il ?",o:["Un type de réseau pour les données","Une approche architecturale décentralisée où chaque domaine métier possède et expose ses données; GCP le soutient via Dataplex pour la gouvernance et BigQuery pour l'analyse","Un service de stockage distribué","Un outil de migration de données"],a:1,e:"Le Data Mesh décentralise la propriété des données par domaine métier. GCP le soutient avec Dataplex (gouvernance des données distribuées), BigQuery (analyse unifiée), Data Catalog (découverte des données) et Pub/Sub (échange d'événements entre domaines)."},
  {t:"Récap Global",q:"Quel service GCP choisir pour exécuter un job batch de traitement de données qui dure 2 heures et peut tolérer une interruption ?",o:["Compute Engine avec des VMs standard","Compute Engine avec des VMs Spot (préemptibles) — 60-90% moins chères que les VMs standard, idéales pour les jobs batch tolérants aux interruptions","Cloud Functions pour les jobs batch","Cloud Run pour les traitements longs"],a:1,e:"Les VMs Spot (Spot VMs, anciennement préemptibles) sont idéales pour les jobs batch tolérants aux interruptions : elles coûtent 60-90% moins qu'une VM standard, avec une durée max de 24h et peuvent être récupérées par GCP avec un préavis de 30 secondes."},
  {t:"Récap Global",q:"Comment Google Cloud Network assure-t-il une faible latence mondiale ?",o:["Via des câbles satellite uniquement","Via un réseau privé mondial (fibres sous-marines, points de présence), des CDN Points of Presence (PoPs) et le routage du trafic sur le réseau Google (cold potato routing)","Via des serveurs dans chaque pays","Via des protocoles de routage internet standard uniquement"],a:1,e:"GCP dispose d'un réseau privé mondial avec des câbles sous-marins propriétaires, des centaines de PoPs pour Cloud CDN, et applique le 'hot potato routing' entrant / 'cold potato routing' sortant pour minimiser la latence sur son infrastructure."},
  {t:"Récap Global",q:"Qu'est-ce que la 'shadow IT' et comment Workspace/GCP aident-ils les organisations à la gérer ?",o:["Une forme de piratage informatique","L'utilisation non autorisée par les employés d'outils tech non approuvés; Workspace fournit des outils collaboratifs officiels approuvés réduisant le besoin de solutions non autorisées","Un service de surveillance des employés","Un type de cloud privé non officiel"],a:1,e:"La shadow IT est l'utilisation d'outils tech non approuvés par les employés (ex: Dropbox personnel pour partager des fichiers pro). Google Workspace réduit ce risque en fournissant des outils collaboratifs officiels approuvés et performants."},
  {t:"Récap Global",q:"Quel est le rôle d'un 'Cloud Center of Excellence' (CCoE) dans une transformation GCP ?",o:["Un centre de données physique Google","Une équipe interne qui définit les standards, best practices, formations et gouvernance pour l'adoption du cloud dans toute l'organisation","Un service de consultation Google payant","Un programme de certification interne"],a:1,e:"Un Cloud Center of Excellence (CCoE) est une équipe transverse définissant les normes d'architecture cloud, les politiques de gouvernance, les formations, les modèles de coûts et accompagnant les équipes métier dans leur adoption du cloud."},
  {t:"Récap Global",q:"Comment GCP aide-t-il à la conformité PCI-DSS pour le traitement des paiements ?",o:["GCP n'est pas certifié PCI-DSS","GCP est certifié PCI-DSS niveau 1; les clients peuvent construire des environnements conformes en utilisant les contrôles de réseau, chiffrement, IAM et les services managés certifiés","La conformité PCI-DSS est automatique sur GCP","Uniquement avec des services Google Pay"],a:1,e:"GCP est certifié PCI-DSS Niveau 1 (le plus élevé). Les clients peuvent construire des environnements de traitement de paiements conformes grâce aux contrôles réseau (VPC), chiffrement (KMS), IAM, logging et services managés certifiés."},
  {t:"Récap Global",q:"Qu'est-ce que 'Looker Studio' (anciennement Google Data Studio) ?",o:["Un service de stockage de données","Un outil de visualisation de données et création de rapports interactifs gratuit, connecté à BigQuery, Sheets et d'autres sources de données","Un service de business intelligence payant enterprise","Un outil de modélisation de données"],a:1,e:"Looker Studio est l'outil gratuit de Google pour créer des tableaux de bord et rapports interactifs. Il se connecte à BigQuery, Google Sheets, Analytics, et plus de 800 connecteurs partenaires pour visualiser les données sans code."},
  {t:"Récap Global",q:"Quel est le service GCP pour l'analyse de sentiment de texte, la traduction et l'extraction d'entités ?",o:["Vertex AI AutoML uniquement","Natural Language API (analyse de sentiment, extraction d'entités, classification de contenu) et Translation API (traduction), des APIs IA pré-entraînées prêtes à l'emploi","Cloud Functions","BigQuery ML"],a:1,e:"Natural Language API analyse le texte : sentiment (positif/négatif), entités nommées, syntaxe, et classification de contenu. Translation API traduit entre 100+ langues. Ces APIs sont pré-entraînées par Google, utilisables sans expertise ML."},
  {t:"Récap Global",q:"Comment GCP soutient-il les pratiques DevOps ?",o:["GCP ne propose pas d'outils DevOps","Via Cloud Build (CI/CD), Artifact Registry (gestion des conteneurs), Cloud Deploy (livraison continue), Cloud Monitoring/Logging (observabilité), et l'intégration avec GitHub/GitLab","DevOps nécessite uniquement des outils open source","Via uniquement des services de formation"],a:1,e:"GCP fournit un outillage DevOps complet : Cloud Build pour l'intégration continue, Artifact Registry pour les images, Cloud Deploy pour la livraison continue, Cloud Monitoring/Trace/Logging pour l'observabilité, et des intégrations Git."},
  {t:"Récap Global",q:"Quelle est la valeur ajoutée de Google Cloud pour une PME par rapport à un hébergement web classique ?",o:["Aucune valeur ajoutée pour les PME","Scalabilité sans provisionnement préalable, accès aux mêmes outils IA/analytics que les grandes entreprises, infrastructure mondiale, paiement à l'usage et réduction des coûts IT fixes","GCP est uniquement pour les grandes entreprises","L'hébergement classique est plus économique dans tous les cas"],a:1,e:"Pour les PME, GCP offre : scalabilité automatique sans investissement initial en serveurs, accès aux technologies IA/BigQuery auparavant réservées aux grandes entreprises, présence mondiale immédiate et modèle OPEX (paiement à l'usage vs CAPEX)."},
  {t:"Récap Global",q:"Qu'est-ce que le programme 'Google Cloud Partner Advantage' ?",o:["Un programme de récompenses pour les clients GCP","Un programme pour les entreprises partenaires (revendeurs, intégrateurs, ISV) offrant certifications, compétences spécialisées, support et avantages commerciaux","Un programme de certification individuelle","Un service de conseil Google interne"],a:1,e:"Google Cloud Partner Advantage est l'écosystème de partenaires : revendeurs (qui vendent GCP), intégrateurs système (qui déploient des solutions), ISV (qui construisent sur GCP) et agences, avec des spécialisations, formations et support."},
  {t:"Récap Global",q:"Un Cloud Digital Leader doit comprendre les concepts des 6 R de la migration. Qu'est-ce que 'Re-platform' ?",o:["Reconstruire complètement l'application","Migrer l'application avec des optimisations mineures (ex: passer de MySQL auto-géré à Cloud SQL) sans la réécrire entièrement","Migrer sans aucun changement (lift-and-shift)","Retirer l'application"],a:1,e:"Re-platform (ou lift-tinker-and-shift) consiste à migrer l'application avec des optimisations mineures pour bénéficier du cloud (ex: utiliser Cloud SQL au lieu d'une VM MySQL) sans refactoriser entièrement l'architecture."},
  {t:"Récap Global",q:"Quel est le principe de 'least privilege' (moindre privilège) dans IAM et pourquoi est-il important ?",o:["Accorder le maximum de droits pour éviter les blocages","N'accorder que les permissions strictement nécessaires à chaque identité pour sa fonction, réduisant la surface d'attaque en cas de compromission","Accorder les droits par département entier","Utiliser uniquement des rôles prédéfinis"],a:1,e:"Le principe de moindre privilège consiste à n'accorder que les permissions minimales nécessaires. En cas de compromission d'un compte, l'attaquant ne peut faire que ce que ce compte pouvait faire, limitant l'impact de la brèche."},
  {t:"Récap Global",q:"Qu'est-ce que la 'scalabilité horizontale' vs 'verticale' et pourquoi le cloud privilégie-t-il l'horizontale ?",o:["Les deux approches sont équivalentes dans le cloud","Verticale = augmenter la puissance d'une machine (limité); Horizontale = ajouter plus de machines (quasi illimitée); le cloud privilégie l'horizontale car elle est plus résiliente et suit la demande dynamiquement","Le cloud n'offre que la scalabilité verticale","La scalabilité horizontale est uniquement pour les bases de données"],a:1,e:"La scalabilité verticale (scale up) atteint des limites physiques et nécessite un arrêt. La scalabilité horizontale (scale out) ajoute des instances à la demande, sans interruption et quasi sans limite — c'est le modèle natif du cloud."},
  {t:"Récap Global",q:"Quelle est la meilleure façon d'optimiser les coûts GCP pour une charge de travail qui tourne 24h/7j depuis plus d'un an ?",o:["Utiliser des VMs Spot","Committed Use Discounts (CUD) sur 1 ou 3 ans offrant jusqu'à 70% de réduction pour les ressources Compute Engine/Cloud SQL utilisées de manière prévisible","Réduire les spécifications matérielles","Migrer vers un autre fournisseur cloud"],a:1,e:"Pour les charges stables et prévisibles, les CUD (Committed Use Discounts) sur 1 ou 3 ans offrent 37-70% de réduction sur Compute Engine, Cloud SQL, etc. Les SUDs (Sustained Use Discounts) s'appliquent automatiquement pour les VMs qui tournent plus de 25% du mois."}
];

// Compléments Jour 4 (IA/ML) — 4 questions manquantes
window.QDATA[4].push(
  {t:"Vertex AI",q:"Qu'est-ce que Vertex AI Model Registry ?",o:["Un annuaire de modèles ML open source","Un référentiel centralisé pour gérer, versionner et déployer les modèles ML entraînés avec Vertex AI","Un service de stockage de fichiers de modèles","Un outil de monitoring des modèles uniquement"],a:1,e:"Vertex AI Model Registry permet de cataloguer, versionner et gérer les modèles ML. Chaque version d'un modèle est trackée avec ses métriques d'entraînement, facilitant la comparaison de versions et le déploiement."},
  {t:"Vertex AI",q:"Qu'est-ce que Vertex AI Feature Store ?",o:["Un magasin d'applications IA","Un référentiel centralisé pour stocker, partager et servir les features ML entre plusieurs équipes et modèles, évitant la duplication","Un service de gestion des données d'entraînement","Un outil de visualisation des features"],a:1,e:"Feature Store centralise les features ML (caractéristiques calculées à partir des données brutes) pour les réutiliser entre projets et modèles, assurer la cohérence train/serving et accélérer le développement ML."},
  {t:"IA Responsable",q:"Qu'est-ce que la 'fairness' (équité) dans l'IA selon Google ?",o:["Facturer les clients de manière équitable","S'assurer que les modèles ML ne produisent pas de résultats discriminatoires systématiques envers des groupes de personnes","Un principe comptable pour les revenus de l'IA","La répartition équitable des ressources GPU"],a:1,e:"La fairness IA consiste à détecter et corriger les biais dans les modèles ML qui pourraient défavoriser certains groupes (genre, ethnie, âge). Vertex AI inclut des outils What-If Tool et Model Cards pour analyser l'équité."},
  {t:"MLOps",q:"Qu'est-ce que la 'feature drift' dans le contexte MLOps ?",o:["Une dérive du budget ML","Le changement dans la distribution statistique des données d'entrée au fil du temps, pouvant dégrader la performance du modèle","Une mise à jour automatique des features","Une erreur dans le code de preprocessing"],a:1,e:"La feature drift (ou data drift) se produit quand les données de production dérivent des données d'entraînement (ex: comportements utilisateurs qui évoluent). Vertex AI Model Monitoring détecte ces dérives et alerte pour déclencher un ré-entraînement."}
);

// Compléments Jour 5 (Sécurité) — 9 questions manquantes
window.QDATA[5].push(
  {t:"IAM",q:"Qu'est-ce qu'un 'Service Account Key' et pourquoi faut-il l'utiliser avec précaution ?",o:["Une clé API pour les utilisateurs humains","Un fichier JSON contenant les credentials d'un service account; à utiliser avec précaution car sa compromission donne un accès complet aux ressources autorisées","Une clé de chiffrement pour les services","Un token d'authentification temporaire"],a:1,e:"Les clés de service account sont des credentials persistants pouvant être volés si mal gérés. La best practice est de préférer les 'Workload Identity' (authentification sans clé) et les credentials temporaires plutôt que des clés JSON à long terme."},
  {t:"IAM",q:"Qu'est-ce que les 'IAM Conditions' dans GCP ?",o:["Des conditions générales d'utilisation de GCP","Des attributs ajoutés aux liaisons IAM pour restreindre les accès selon des critères (heure, adresse IP, étiquette de ressource, état de l'appareil)","Des filtres pour les logs IAM","Des règles de facturation conditionnelles"],a:1,e:"Les IAM Conditions permettent d'ajouter des contraintes contextuelles aux autorisations : accès uniquement pendant les heures ouvrées, depuis une IP spécifique, pour des ressources avec une étiquette particulière, ou depuis un appareil géré."},
  {t:"Sécurité réseau",q:"Qu'est-ce que Cloud NAT (Network Address Translation) ?",o:["Un service de translation de noms de domaine","Un service permettant aux VMs sans adresse IP publique d'accéder à internet de façon sortante, sans exposer d'IP publique entrante","Un protocole d'adressage réseau privé","Un service de load balancing réseau"],a:1,e:"Cloud NAT permet à des VMs avec uniquement des IPs privées (pas d'IP publique) d'accéder à internet (mises à jour, APIs externes) sans exposer ces VMs à des connexions entrantes depuis internet — améliorant la posture de sécurité."},
  {t:"Sécurité réseau",q:"Qu'est-ce que Private Google Access ?",o:["Un service VPN entre GCP et on-premises","Une fonctionnalité permettant aux VMs sans IP publique d'accéder aux APIs Google (Cloud Storage, BigQuery) sans passer par internet public","Un réseau privé entre projets GCP","Un service de connexion privée aux APIs tierces"],a:1,e:"Private Google Access permet aux instances Compute Engine avec seulement des IPs privées d'accéder aux services et APIs Google via l'infrastructure interne Google, sans sortir sur internet public — réduisant la surface d'exposition."},
  {t:"Conformité",q:"Qu'est-ce que SOC 2 Type II et son importance pour GCP ?",o:["Un standard uniquement pour les services financiers","Un rapport d'audit indépendant vérifiant que Google a maintenu les contrôles de sécurité, disponibilité et confidentialité sur une période définie (généralement 12 mois)","Une certification de performance des serveurs","Un standard de qualité logicielle"],a:1,e:"SOC 2 Type II atteste qu'un auditeur indépendant a vérifié que Google Cloud maintient ses contrôles (sécurité, disponibilité, intégrité, confidentialité) sur une durée prolongée — cruciale pour la due diligence des clients entreprise."},
  {t:"Conformité",q:"Qu'est-ce qu'une 'Shared Fate' (destin partagé) dans la sécurité cloud selon Google ?",o:["Un partage des responsabilités uniquement sur les coûts","Google va au-delà du modèle 'shared responsibility' en proposant proactivement des blueprints sécurisés, des outils de validation et des meilleures pratiques pour aider les clients à bien sécuriser leurs déploiements","Un service d'assurance cyber partagé","Un programme de pénalités en cas de faille"],a:1,e:"'Shared Fate' est la vision de Google qui considère sa réputation liée à la sécurité de ses clients. Google fournit proactivement des blueprints sécurisés (Security Foundations Blueprint), des outils Security Health Analytics et des recommandations."},
  {t:"IAM",q:"Qu'est-ce que Workload Identity Federation ?",o:["Une fédération d'identité pour les utilisateurs humains","Un mécanisme permettant aux workloads s'exécutant hors GCP (AWS, Azure, on-premises, GitHub Actions) d'accéder aux ressources GCP sans clés de service account","Un service de SSO pour les applications","Un outil de gestion des identités multi-cloud"],a:1,e:"Workload Identity Federation permet aux applications s'exécutant sur d'autres plateformes (AWS EC2, Azure, GitHub Actions, on-premises) de s'authentifier à GCP via des tokens temporaires, sans créer ni stocker de clés de service account."},
  {t:"Sécurité données",q:"Qu'est-ce que le chiffrement 'at rest' par défaut dans GCP ?",o:["Un chiffrement optionnel à activer manuellement","GCP chiffre automatiquement toutes les données stockées (Cloud Storage, Persistent Disk, etc.) en AES-256 par défaut, sans configuration requise","Un chiffrement uniquement pour les données sensibles","Un service payant supplémentaire"],a:1,e:"GCP chiffre automatiquement toutes les données au repos avec AES-256, sans action requise du client. Pour plus de contrôle, les clients peuvent utiliser CMEK (clés gérées par le client via Cloud KMS) ou CSEK (clés fournies par le client)."},
  {t:"Sécurité réseau",q:"Qu'est-ce que les 'Firewall Rules' hiérarchiques dans GCP ?",o:["Des règles de pare-feu applicables uniquement au niveau projet","Des règles définies au niveau Organisation ou Dossier qui s'appliquent à tous les VPC sous-jacents, avec priorité sur les règles de pare-feu de projet","Des règles automatiques créées par GCP","Des règles de pare-feu pour les conteneurs uniquement"],a:1,e:"Les Hierarchical Firewall Policies permettent aux administrateurs de définir des règles centralisées au niveau Organisation ou Dossier qui s'imposent à tous les projets, empêchant les équipes de les contourner — idéal pour les règles de sécurité d'entreprise."}
);

// Compléments Jour 6 (Workspace) — 5 questions manquantes
window.QDATA[6].push(
  {t:"Google Workspace",q:"Qu'est-ce que Google Forms dans Workspace ?",o:["Un outil de gestion des formulaires administratifs","Un outil de création de questionnaires, sondages et quiz en ligne avec collecte automatique des réponses dans Google Sheets","Un service de signature de formulaires légaux","Un outil de génération de formulaires PDF"],a:1,e:"Google Forms permet de créer facilement des questionnaires, sondages, quiz ou inscriptions. Les réponses sont automatiquement collectées et organisées dans Google Sheets pour analyse. Les résultats peuvent être visualisés en temps réel."},
  {t:"Collaboration",q:"Qu'est-ce que la fonctionnalité 'History' (historique des versions) dans Google Docs ?",o:["Un simple journal des modifications","Un système complet de gestion de versions permettant de voir qui a modifié quoi et quand, et de restaurer n'importe quelle version précédente","Un service de sauvegarde externe","Un outil de comparaison de documents"],a:1,e:"L'historique des versions Google Docs enregistre automatiquement chaque modification avec horodatage et auteur. On peut voir les changements, nommer des versions clés, et restaurer n'importe quelle version antérieure — sans limite de durée."},
  {t:"Workspace Admin",q:"Qu'est-ce que les groupes Google dans Workspace ?",o:["Des groupes de sécurité réseau uniquement","Des listes de distribution email et espaces collaboratifs permettant d'envoyer des emails, partager des ressources et gérer les permissions pour un ensemble d'utilisateurs","Des groupes de facturation","Des équipes de support Google"],a:1,e:"Les Google Groups dans Workspace servent de listes de distribution email, de forums de discussion, et de mécanismes de gestion d'accès. On peut partager un Drive, un calendrier ou accorder des permissions IAM à un groupe entier."},
  {t:"Workspace Intégration",q:"Comment Google Calendar s'intègre-t-il avec Google Meet dans Workspace ?",o:["Aucune intégration directe","Les invitations Calendar incluent automatiquement un lien Google Meet, et les réunions peuvent être lancées directement depuis Calendar sans quitter l'application","L'intégration nécessite un add-on payant","Calendar envoie uniquement des rappels Meet"],a:1,e:"Google Calendar et Meet sont profondément intégrés : chaque événement peut inclure un lien Meet généré automatiquement, les participants rejoignent depuis Calendar ou l'invitation email, et les enregistrements de réunion apparaissent dans l'événement."},
  {t:"Sécurité Workspace",q:"Qu'est-ce que le 'Security Center' dans Google Workspace ?",o:["Un centre de données sécurisé","Un tableau de bord unifié de sécurité pour Workspace fournissant des analyses de sécurité, l'état de santé des configurations, des alertes et des recommandations d'amélioration","Un service de surveillance physique","Un outil de gestion des certificats SSL"],a:1,e:"Le Security Center de Workspace (disponible en Enterprise) offre un tableau de bord unifié : métriques de sécurité en temps réel, analyse des menaces, état des configurations, alertes et recommandations pour améliorer la posture de sécurité Workspace."}
);
